// A person as a coloured round badge with their initials: the gantt's tooltip
// and its task panel both show who a task is for this way, so a face can be
// found at a glance. The colour is the kanban board's stable hash of the name,
// so a person wears the same colour wherever they turn up.

import * as React from 'react';
import { autoSwatch } from '../kanban';
import { initialsOf } from '../ganttplan';
import { contrastText } from '../ganttstyle';

export function personColor(person: string): string {
    return autoSwatch(person).hex;
}

export default function PersonBadge({ person, size = 22 }: { person: string; size?: number }) {
    const bg = personColor(person);
    return (
        <span
            aria-hidden
            style={{
                display: 'inline-flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0,
                width: size, height: size, borderRadius: '50%', background: bg, color: contrastText(bg),
                fontSize: Math.round(size * 0.42), fontWeight: 700, letterSpacing: '0.02em', lineHeight: 1,
                boxShadow: '0 0 0 1.5px rgba(255,255,255,0.35)',
            }}
        >
            {initialsOf(person)}
        </span>
    );
}
