// The "only open todos" switch on a saved query.
//
// It is written into the saved text rather than kept as a flag beside it. A
// saved query is read by the kanban, gantt, mind map and drill tabs, and each
// of them runs the text it is given with its own base filter (or none) - so a
// flag would mean teaching all four about it, and any that missed it would
// quietly answer a different question from the one on this page. Written into
// the text, what the table shows is exactly what every tab runs.
//
// The editor reads it back out again, so the switch survives a round trip:
// `TODO_FILTER && (query)` is recognised and split into the switch and the
// query underneath. Anything else - including the same words typed by hand in
// another order - is left as the query, switch off, which is never wrong:
// the text still says what it does.

export const TODO_FILTER = '!IsArchived() && IsTodo()';

// The text to save for a query with the switch on or off.
export function withTodoFilter(query: string, todosOnly: boolean): string {
    const q = (query || '').trim();
    if (!todosOnly) return q;
    if (q === '') return TODO_FILTER;
    return `${TODO_FILTER} && (${q})`;
}

// Whether `s` is one bracketed group from end to end. `(a) || (b)` starts and
// ends with a bracket and is not one, which is the case stripping them would
// get wrong.
function wrapped(s: string): boolean {
    if (s.charAt(0) !== '(' || s.charAt(s.length - 1) !== ')') return false;
    let depth = 0;
    let quote = '';
    for (let i = 0; i < s.length; i++) {
        const c = s.charAt(i);
        if (quote) {
            if (c === '\\') { i += 1; continue; }
            if (c === quote) quote = '';
            continue;
        }
        if (c === '"' || c === "'") quote = c;
        else if (c === '(') depth += 1;
        else if (c === ')') {
            depth -= 1;
            if (depth === 0 && i < s.length - 1) return false;
        }
    }
    return depth === 0;
}

// A saved text taken apart into the switch and the query under it.
export function splitTodoFilter(saved: string): { query: string; todosOnly: boolean } {
    const s = (saved || '').trim();
    if (s === TODO_FILTER) return { query: '', todosOnly: true };
    const head = `${TODO_FILTER} && `;
    if (s.indexOf(head) === 0) {
        const rest = s.slice(head.length).trim();
        if (wrapped(rest)) return { query: rest.slice(1, -1).trim(), todosOnly: true };
    }
    return { query: s, todosOnly: false };
}

// Renaming a query: everything that names it by its old name, pointed at the
// new one. Only the things that changed are returned, so nothing that did not
// mention the query is written back.
export function renamed<T extends { storedQuery?: string }>(items: T[], from: string, to: string): { all: T[]; changed: number } {
    let changed = 0;
    const all = items.map(it => {
        if (it.storedQuery !== from) return it;
        changed += 1;
        return { ...it, storedQuery: to };
    });
    return { all, changed };
}
