// Making a new org file: which folder it goes in, picked fzf-style from every
// folder under the org directories, and the path that makes.
//
// Pure, and tested in newfile.test.ts; components/NewFileDialog.tsx draws it.

import { fuzzyScore, fuzzyTerms } from './fuzzy';

// The org directories themselves: the folders no other folder in the list
// contains. The server sends them along with everything under them.
export function rootsOf(dirs: string[]): string[] {
    const clean = dirs.map(d => d.replace(/\/+$/, '')).filter(Boolean);
    return clean.filter(d => !clean.some(o => o !== d && d.startsWith(o + '/')));
}

// A folder as a person reads it: from its org directory's own name down,
// "gtd/ian/roblox" rather than "/Users/me/dev/gtd/ian/roblox".
export function dirLabel(dir: string, roots: string[]): string {
    const d = dir.replace(/\/+$/, '');
    let best = '';
    for (const r of roots) if ((d === r || d.startsWith(r + '/')) && r.length > best.length) best = r;
    if (!best) return d;
    const base = best.split('/').pop() || best;
    return d === best ? base : `${base}/${d.slice(best.length + 1)}`;
}

export type RankedDir = { dir: string; label: string; score: number; hits: number[] };

// Where each letter of a term landed in the text, for drawing the match the
// way fzf does. Greedy and left to right, which is how fuzzyScore matches.
export function matchPositions(terms: string[], text: string): number[] {
    const low = text.toLowerCase();
    const out = new Set<number>();
    for (const t of terms) {
        // A whole-word run is the better thing to light, when there is one.
        const at = low.indexOf(t);
        if (at >= 0) {
            for (let i = 0; i < t.length; i++) out.add(at + i);
            continue;
        }
        let ti = 0;
        for (let i = 0; i < low.length && ti < t.length; i++) {
            if (low[i] === t[ti]) { out.add(i); ti++; }
        }
    }
    return Array.from(out).sort((a, b) => a - b);
}

// The folders that match what is typed, best first. Every term has to match
// the label (fuzzily, in order within the term); a term matching the last
// part of the path counts for more, since that is the folder's own name.
// Nothing typed: every folder, shallowest first, then by name.
export function rankDirs(dirs: string[], filter: string, roots: string[]): RankedDir[] {
    const terms = fuzzyTerms(filter);
    const out: RankedDir[] = [];
    for (const dir of dirs) {
        const label = dirLabel(dir, roots);
        const leaf = label.split('/').pop() || label;
        let score = 0;
        let ok = true;
        for (const t of terms) {
            const onLeaf = fuzzyScore(t, leaf);
            const onAll = fuzzyScore(t, label);
            if (onAll === null) { ok = false; break; }
            score += onLeaf !== null ? onLeaf * 2 : onAll;
        }
        if (!ok) continue;
        out.push({ dir, label, score, hits: terms.length ? matchPositions(terms, label) : [] });
    }
    const depth = (l: string) => l.split('/').length;
    out.sort((a, b) => (b.score - a.score) || (depth(a.label) - depth(b.label)) || a.label.localeCompare(b.label));
    return out;
}

// What is wrong with a file or folder name, or ''. A folder may be several
// levels ("projects/2026"); a file name is one.
export function nameError(name: string, kind: 'file' | 'folder'): string {
    const n = name.trim();
    if (!n) return kind === 'file' ? 'The file needs a name' : 'The folder needs a name';
    if (/[\\:*?"<>|]/.test(n)) return 'Leave out \\ : * ? " < > |';
    const parts = n.split('/');
    if (parts.some(p => p === '..' || p === '.')) return 'No . or .. in the name';
    if (kind === 'file' && parts.length > 1) return 'A file name has no / in it - make a new folder for that';
    if (parts.some(p => p.trim() === '')) return 'An empty folder name';
    if (parts.some(p => p.startsWith('.'))) return 'A name starting with . would be hidden';
    return '';
}

// The new file's path: the folder picked, then the new folder if there is
// one, then the name with .org on the end.
export function newFilePath(parent: string, newFolder: string, name: string): string {
    const bits = [parent.replace(/\/+$/, '')];
    const folder = newFolder.trim().replace(/^\/+|\/+$/g, '');
    if (folder) bits.push(folder);
    const n = name.trim();
    bits.push(/\.org$/i.test(n) ? n : `${n}.org`);
    return bits.join('/');
}

// A title from a file name: "q3-planning_notes" reads as "Q3 Planning Notes".
export function titleFromName(name: string): string {
    return name.trim().replace(/\.org$/i, '').split(/[-_\s]+/).filter(Boolean)
        .map(w => w[0].toUpperCase() + w.slice(1)).join(' ');
}

// A template as a person reads it: "new/project.tpl" is "Project".
export function templateLabel(t: string): string {
    const base = (t.split('/').pop() || t).replace(/\.tpl$/, '');
    return titleFromName(base);
}
