// A file's git history drawn as a graph: the Diff tab's history list. Pure.
//
// The server hands over commits newest first with their parents rewritten to
// the commits that touched the file (`git log --parents -- file`), so merges
// and branches that never touched it fall away and what is left is the shape
// of this file's history. `layoutGraph` gives each commit a lane and each row
// the line segments crossing it, which the list draws as an svg strip.
//
// Lanes are columns that a line of history runs down. A commit takes the lane
// that was waiting for it (its child put it there), or the first free one; its
// first parent inherits the lane and its colour, so a branch is one colour all
// the way down; any further parent (a merge) gets a lane of its own, or joins
// the lane already waiting for that commit.

export type GraphCommit = {
    Hash: string;
    Parents: string[];
};

// What /history answers, field for field with HistoryResult in
// internal/app/orgs/filehistory.go.
export type HistoryCommit = GraphCommit & {
    Short: string;
    Author: string;
    Email: string;
    When: number; // unix seconds
    Subject: string;
    Refs: string[] | null;
    Added: number;
    Removed: number;
};

export type HistoryResult = {
    Ok: boolean;
    Msg: string;
    File: string;
    InRepo: boolean;
    Repo: string;
    Path: string;
    Branch: string;
    Head: string;
    Last: string;
    Untracked: boolean;
    Staged: boolean;
    StagedAdd: number;
    StagedDel: number;
    Modified: boolean;
    ModifiedAdd: number;
    ModifiedDel: number;
    Commits: HistoryCommit[] | null;
    Truncated: boolean;
};

export type FileAtRev = { Ok: boolean; Msg: string; Rev: string; Text: string; Missing: boolean };

// The revisions that are not commits. EMPTY is the side of a comparison
// before the file existed: the commit that created it is compared with it.
export const WORKING = 'WORKING';
export const INDEX = 'INDEX';
export const EMPTY = 'EMPTY';

// A line through one row, drawn in two halves: from the row's top edge down to
// its middle, and from the middle to its bottom edge. A straight run has the
// same lane at both ends; a branch or merge bends from one lane to another.
export type Segment = { from: number; to: number; color: number };

export type GraphRow = {
    lane: number;        // where the commit's dot goes
    color: number;       // the dot's colour index
    up: Segment[];       // top edge (from) to middle (to)
    down: Segment[];     // middle (from) to bottom edge (to)
    width: number;       // lanes in use across this row
};

export type Graph = { rows: GraphRow[]; lanes: number };

export function layoutGraph(commits: GraphCommit[]): Graph {
    // lanes[i]: the hash the line in lane i is heading down to, or null.
    const lanes: (string | null)[] = [];
    const colors: number[] = [];
    let nextColor = 0;
    const rows: GraphRow[] = [];
    let widest = 0;

    for (const c of commits) {
        const before = lanes.slice();
        const beforeColors = colors.slice();

        // The lanes that were waiting for this commit. More than one means
        // several children converge on it here.
        const waiting: number[] = [];
        before.forEach((h, i) => { if (h === c.Hash) waiting.push(i); });
        let lane: number;
        let color: number;
        if (waiting.length > 0) {
            lane = waiting[0];
            color = beforeColors[lane];
        } else {
            lane = lanes.indexOf(null);
            if (lane < 0) lane = lanes.length;
            color = nextColor++;
        }

        const up: Segment[] = [];
        before.forEach((h, i) => {
            if (h === null) return;
            up.push({ from: i, to: h === c.Hash ? lane : i, color: beforeColors[i] });
        });

        // Free the converging lanes, then hand the lane on to the first parent.
        // `fresh` are lanes whose line starts at this commit's dot; `joins`
        // are lanes already running that a parent of this commit joins, which
        // keep their straight line and get a bend across from the dot.
        waiting.forEach(i => { lanes[i] = null; });
        while (lanes.length <= lane) { lanes.push(null); colors.push(0); }
        const fresh = new Set<number>();
        const joins: number[] = [];
        const parents = c.Parents || [];
        parents.forEach((p, k) => {
            const at = lanes.indexOf(p);
            if (at >= 0) { joins.push(at); return; }
            let slot = k === 0 ? lane : -1;
            if (slot < 0) {
                for (let i = 0; i < lanes.length; i++) if (lanes[i] === null && i !== lane) { slot = i; break; }
            }
            if (slot < 0) { slot = lanes.length; lanes.push(null); colors.push(0); }
            lanes[slot] = p;
            colors[slot] = k === 0 ? color : nextColor++;
            fresh.add(slot);
        });

        const down: Segment[] = [];
        lanes.forEach((h, i) => {
            if (h !== null) down.push({ from: fresh.has(i) ? lane : i, to: i, color: colors[i] });
        });
        // The bend is drawn in this commit's colour: it is this line ending.
        joins.forEach(j => down.push({ from: lane, to: j, color }));

        // Trailing empty lanes are given back, so the strip narrows again
        // once a branch has merged.
        while (lanes.length > 0 && lanes[lanes.length - 1] === null) { lanes.pop(); colors.pop(); }

        const width = Math.max(lane + 1, before.length, lanes.length);
        widest = Math.max(widest, width);
        rows.push({ lane, color, up, down, width });
    }
    // Lines left hanging at the bottom (history cut short) simply run off the
    // last row, which is what they are doing.
    return { rows, lanes: widest };
}

// The palette lanes are coloured from, in order. Chosen to read on both the
// light and dark grounds; a lane's colour is its index modulo the length.
export const LANE_COLORS = [
    '#3b82f6', // blue
    '#10b981', // green
    '#f59e0b', // amber
    '#ec4899', // pink
    '#8b5cf6', // violet
    '#06b6d4', // cyan
    '#ef4444', // red
    '#84cc16', // lime
];

export function laneColor(i: number): string {
    return LANE_COLORS[((i % LANE_COLORS.length) + LANE_COLORS.length) % LANE_COLORS.length];
}

// "3 days ago", "just now": history is read by how long ago, and the exact
// time is a tooltip.
export function relativeTime(when: number, now: number = Date.now() / 1000): string {
    const s = Math.max(0, Math.round(now - when));
    if (s < 45) return 'just now';
    const m = Math.round(s / 60);
    if (m < 60) return `${m} min ago`;
    const h = Math.round(s / 3600);
    if (h < 24) return `${h} hour${h === 1 ? '' : 's'} ago`;
    const d = Math.round(s / 86400);
    if (d < 7) return d === 1 ? 'yesterday' : `${d} days ago`;
    if (d < 30) { const w = Math.round(d / 7); return `${w} week${w === 1 ? '' : 's'} ago`; }
    if (d < 365) { const mo = Math.round(d / 30); return `${mo} month${mo === 1 ? '' : 's'} ago`; }
    const y = Math.round(d / 365);
    return `${y} year${y === 1 ? '' : 's'} ago`;
}

// The initials an author's avatar shows, and a hue that is theirs in every
// browser.
export function initials(name: string): string {
    const parts = name.trim().split(/\s+/).filter(p => p !== '');
    if (parts.length === 0) return '?';
    if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
    return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

export function authorHue(name: string): number {
    let h = 0;
    for (let i = 0; i < name.length; i++) h = (h * 31 + name.charCodeAt(i)) >>> 0;
    return h % 360;
}

// A ref as git's %D spells it, sorted into what kind of chip it is.
export type RefChip = { label: string; kind: 'head' | 'branch' | 'remote' | 'tag' };

export function refChips(refs: string[] | null | undefined): RefChip[] {
    const out: RefChip[] = [];
    for (const r of refs || []) {
        if (r.startsWith('HEAD -> ')) { out.push({ label: r.slice(8), kind: 'head' }); continue; }
        if (r === 'HEAD') { out.push({ label: 'HEAD', kind: 'head' }); continue; }
        if (r.startsWith('tag: ')) { out.push({ label: r.slice(5), kind: 'tag' }); continue; }
        if (r.includes('/')) {
            if (r.endsWith('/HEAD')) continue; // origin/HEAD says nothing a reader needs
            out.push({ label: r, kind: 'remote' });
            continue;
        }
        out.push({ label: r, kind: 'branch' });
    }
    return out;
}
