import * as React from 'react';
import Box from '@mui/joy/Box';
import Chip from '@mui/joy/Chip';
import Typography from '@mui/joy/Typography';
import CheckCircleRoundedIcon from '@mui/icons-material/CheckCircleRounded';
import AddRoundedIcon from '@mui/icons-material/AddRounded';
import RemoveRoundedIcon from '@mui/icons-material/RemoveRounded';
import EventOutlinedIcon from '@mui/icons-material/EventOutlined';
import DriveFileMoveOutlinedIcon from '@mui/icons-material/DriveFileMoveOutlined';
import EditNoteOutlinedIcon from '@mui/icons-material/EditNoteOutlined';
import LocalOfferOutlinedIcon from '@mui/icons-material/LocalOfferOutlined';
import ReplayRoundedIcon from '@mui/icons-material/ReplayRounded';
import LabelOutlinedIcon from '@mui/icons-material/LabelOutlined';
import FlagOutlinedIcon from '@mui/icons-material/FlagOutlined';

import { OutlineDiff } from '../orgdiff';

// The comparison in one line, told twice: as lines (+12 −4, and the five
// squares a code review shows) and as what happened to the outline, in org's
// words - "2 completed, 1 rescheduled, 1 refiled". The second is what someone
// reading their own notes back actually wants to know.
export default function DiffSummary({ stats, outline, identical, loading }: {
    stats: { added: number; removed: number; changes: number };
    outline: OutlineDiff;
    identical: boolean;
    loading?: boolean;
}) {
    const s = outline.summary;
    const total = stats.added + stats.removed;
    // Five squares, split in proportion, as GitHub draws them.
    const greens = total === 0 ? 0 : Math.round((stats.added / total) * 5);
    const squares = Array.from({ length: 5 }, (_, i) => (total === 0 ? 'none' : i < greens ? 'add' : 'del'));

    type Tone = 'success' | 'warning' | 'primary' | 'danger' | 'neutral';
    const all: { n: number; label: string; icon: React.ReactNode; color: Tone }[] = [
        { n: s.completed, label: 'completed', icon: <CheckCircleRoundedIcon />, color: 'success' },
        { n: s.reopened, label: 'reopened', icon: <ReplayRoundedIcon />, color: 'warning' },
        { n: s.newTasks, label: s.newTasks === 1 ? 'new task' : 'new tasks', icon: <FlagOutlinedIcon />, color: 'primary' },
        { n: s.added - s.newTasks, label: s.added - s.newTasks === 1 ? 'heading added' : 'headings added', icon: <AddRoundedIcon />, color: 'success' },
        { n: s.removed, label: s.removed === 1 ? 'heading removed' : 'headings removed', icon: <RemoveRoundedIcon />, color: 'danger' },
        { n: s.rescheduled, label: 'rescheduled', icon: <EventOutlinedIcon />, color: 'warning' },
        { n: s.moved, label: 'refiled', icon: <DriveFileMoveOutlinedIcon />, color: 'primary' },
        { n: s.renamed, label: 'renamed', icon: <LabelOutlinedIcon />, color: 'neutral' },
        { n: s.retagged, label: 'retagged', icon: <LocalOfferOutlinedIcon />, color: 'neutral' },
        { n: s.edited, label: 'edited', icon: <EditNoteOutlinedIcon />, color: 'neutral' },
    ];
    const story = all.filter(x => x.n > 0);

    return (
        <Box sx={{
            display: 'flex', alignItems: 'center', gap: 1.25, flexWrap: 'wrap',
            px: 1.5, py: 1, borderRadius: 'md', bgcolor: 'background.level1',
            minHeight: 44,
        }}>
            {loading ? (
                <Typography level="body-sm" sx={{ color: 'text.tertiary' }}>Comparing…</Typography>
            ) : identical ? (
                <Typography level="body-sm" sx={{ color: 'text.tertiary' }}>No differences</Typography>
            ) : (
                <>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.75 }}>
                        <Typography level="title-sm" sx={{ color: 'success.plainColor', fontVariantNumeric: 'tabular-nums' }}>
                            +{stats.added}
                        </Typography>
                        <Typography level="title-sm" sx={{ color: 'danger.plainColor', fontVariantNumeric: 'tabular-nums' }}>
                            −{stats.removed}
                        </Typography>
                        <Box sx={{ display: 'flex', gap: '2px' }}>
                            {squares.map((k, i) => (
                                <Box key={i} sx={{
                                    width: 8, height: 8, borderRadius: '2px',
                                    bgcolor: k === 'add' ? 'success.400' : k === 'del' ? 'danger.400' : 'neutral.300',
                                }} />
                            ))}
                        </Box>
                        <Typography level="body-xs" sx={{ color: 'text.tertiary', ml: 0.5 }}>
                            in {stats.changes} place{stats.changes === 1 ? '' : 's'}
                        </Typography>
                    </Box>
                    {story.length > 0 && <Box sx={{ width: '1px', alignSelf: 'stretch', bgcolor: 'divider' }} />}
                    <Box sx={{ display: 'flex', gap: 0.75, flexWrap: 'wrap' }}>
                        {story.map(x => (
                            <Chip key={x.label} size="sm" variant="soft" color={x.color} startDecorator={x.icon}
                                sx={{ '--Chip-decoratorChildHeight': '16px', fontWeight: 500 }}>
                                {x.n} {x.label}
                            </Chip>
                        ))}
                        {(outline.preamble.added + outline.preamble.removed) > 0 && (
                            <Chip size="sm" variant="outlined" color="neutral">file settings changed</Chip>
                        )}
                    </Box>
                </>
            )}
        </Box>
    );
}
