// The menu a dependency arrow opens when it is clicked: a small red ring
// round the point that was clicked, with a button to take the arrow away and
// one at each end to go to the task it leaves or the task it reaches.
//
// Ephemeral on purpose. It is a quick question about one arrow, so it goes
// away on a click anywhere else, on Escape, on a scroll, or once one of its
// buttons has been pressed. Shared by the svg chart and the vis one, which
// both hand it a point on the screen; it is drawn on the page rather than in
// either chart, so neither chart's clipping or scrolling can cut it off.

import * as React from 'react';
import { createPortal } from 'react-dom';
import CloseRoundedIcon from '@mui/icons-material/CloseRounded';
import WestRoundedIcon from '@mui/icons-material/WestRounded';
import EastRoundedIcon from '@mui/icons-material/EastRounded';
import { GanttTask } from '../gantt';

export type DepMenuAt = { x: number; y: number; from: GanttTask; to: GanttTask };

const RED = '#e5484d';
const RED_DEEP = '#c62f35';
const RING = 38;
const BTN = 26;

// Hover and the staggered pop-in can only be said in a stylesheet.
const STYLES = `
@keyframes gdm-ring { from { transform: scale(0.3); opacity: 0; } to { transform: scale(1); opacity: 1; } }
@keyframes gdm-btn { from { transform: scale(0.2); opacity: 0; } to { transform: scale(1); opacity: 1; } }
.gdm-btn {
    transition: transform 110ms ease, box-shadow 110ms ease, background 110ms ease;
    animation: gdm-btn 160ms cubic-bezier(.2,1.4,.4,1) both;
}
.gdm-btn:not(:disabled):hover, .gdm-btn:not(:disabled):focus-visible {
    transform: scale(1.14); outline: none;
    box-shadow: 0 0 0 3px rgba(229, 72, 77, 0.28), 0 3px 8px rgba(0, 0, 0, 0.28);
}
.gdm-side:not(:disabled):hover, .gdm-side:not(:disabled):focus-visible { background: #fff1f1; }
`;

export default function GanttDepMenu({ at, canRemove, onRemove, onSelect, onClose }: {
    at: DepMenuAt | null;
    // Why the arrow cannot be taken away, when it cannot: '' when it can.
    canRemove: string;
    onRemove: (waits: GanttTask, on: GanttTask) => void;
    onSelect?: (t: GanttTask) => void;
    onClose: () => void;
}) {
    const boxRef = React.useRef<HTMLDivElement>(null);
    const [label, setLabel] = React.useState('');
    React.useEffect(() => {
        if (!at) return;
        setLabel('');
        const away = (e: Event) => {
            if (boxRef.current && e.target instanceof Node && boxRef.current.contains(e.target)) return;
            onClose();
        };
        const key = (e: KeyboardEvent) => { if (e.key === 'Escape') onClose(); };
        // Registered on the next tick, so the click that opened the menu is
        // not also the click that closes it.
        const t = window.setTimeout(() => {
            window.addEventListener('pointerdown', away, true);
            window.addEventListener('wheel', onClose, { passive: true });
            window.addEventListener('scroll', onClose, true);
        }, 0);
        window.addEventListener('keydown', key);
        return () => {
            window.clearTimeout(t);
            window.removeEventListener('pointerdown', away, true);
            window.removeEventListener('wheel', onClose);
            window.removeEventListener('scroll', onClose, true);
            window.removeEventListener('keydown', key);
        };
    }, [at, onClose]);
    if (!at || typeof document === 'undefined') return null;

    const said = `${at.to.name} waits on ${at.from.name}`;
    const button = (
        key: string, dx: number, dy: number, icon: React.ReactNode, tip: string,
        run: (() => void) | null, danger = false, delay = 0,
    ) => (
        <button
            key={key}
            type="button"
            aria-label={tip}
            disabled={!run}
            className={danger ? 'gdm-btn' : 'gdm-btn gdm-side'}
            onMouseEnter={() => setLabel(tip)}
            onMouseLeave={() => setLabel('')}
            onFocus={() => setLabel(tip)}
            onClick={() => { if (run) { onClose(); run(); } }}
            style={{
                position: 'absolute', left: RING + dx - BTN / 2, top: RING + dy - BTN / 2,
                width: BTN, height: BTN, borderRadius: '50%', padding: 0, display: 'flex',
                alignItems: 'center', justifyContent: 'center', cursor: run ? 'pointer' : 'not-allowed',
                border: danger ? '1px solid rgba(255,255,255,0.35)' : '1px solid rgba(229, 72, 77, 0.45)',
                background: danger
                    ? (run ? `linear-gradient(160deg, #f26a6f 0%, ${RED} 45%, ${RED_DEEP} 100%)` : '#c9a3a5')
                    : 'linear-gradient(180deg, #ffffff 0%, #fbeeee 100%)',
                color: danger ? '#fff' : RED_DEEP,
                boxShadow: '0 2px 5px rgba(0,0,0,0.22)', opacity: run ? 1 : 0.55,
                animationDelay: `${delay}ms`,
            }}
        >
            {icon}
        </button>
    );
    const left = Math.min(Math.max(at.x - RING, 4), window.innerWidth - RING * 2 - 4);
    const top = Math.min(Math.max(at.y - RING, 4), window.innerHeight - RING * 2 - 40);
    return createPortal(
        <div
            ref={boxRef}
            role="menu"
            aria-label={said}
            style={{ position: 'fixed', left, top, width: RING * 2, height: RING * 2, zIndex: 2100 }}
        >
            <style>{STYLES}</style>
            {/* A soft ring of red glass rather than a flat disc: clear in the
                middle so the arrow under the click still shows. */}
            <div style={{
                position: 'absolute', inset: 0, borderRadius: '50%',
                background: 'radial-gradient(circle, rgba(229,72,77,0) 34%, rgba(229,72,77,0.13) 36%, rgba(229,72,77,0.2) 100%)',
                border: '1px solid rgba(229, 72, 77, 0.45)',
                boxShadow: '0 6px 18px rgba(198, 47, 53, 0.18), inset 0 0 0 1px rgba(255,255,255,0.25)',
                backdropFilter: 'blur(1.5px)', WebkitBackdropFilter: 'blur(1.5px)',
                animation: 'gdm-ring 140ms ease-out both',
            }} />
            <div style={{
                position: 'absolute', left: RING - 3, top: RING - 3, width: 6, height: 6,
                borderRadius: '50%', background: RED, boxShadow: '0 0 0 2px rgba(255,255,255,0.8)',
            }} />
            {button('rm', 0, -RING + 4, <CloseRoundedIcon sx={{ fontSize: 16 }} />,
                canRemove ? canRemove : `Remove: ${at.to.name} no longer waits on ${at.from.name}`,
                canRemove ? null : () => onRemove(at.to, at.from), true, 30)}
            {button('from', -RING + 8, RING / 2 - 2, <WestRoundedIcon sx={{ fontSize: 14 }} />,
                `Select ${at.from.name}`, onSelect ? () => onSelect(at.from) : null, false, 60)}
            {button('to', RING - 8, RING / 2 - 2, <EastRoundedIcon sx={{ fontSize: 14 }} />,
                `Select ${at.to.name}`, onSelect ? () => onSelect(at.to) : null, false, 90)}
            <div style={{
                position: 'absolute', top: RING * 2 + 6, left: RING, transform: 'translateX(-50%)',
                whiteSpace: 'nowrap', maxWidth: 360, overflow: 'hidden', textOverflow: 'ellipsis',
                background: 'rgba(24, 26, 32, 0.92)', color: '#f4f4f2', borderRadius: 999,
                padding: '3px 10px', fontSize: 11.5, pointerEvents: 'none', letterSpacing: '0.01em',
                boxShadow: `0 3px 10px rgba(0,0,0,0.2), inset 0 0 0 1px rgba(229,72,77,0.5)`,
            }}>
                {label || said}
            </div>
        </div>,
        document.body,
    );
}

// Why an arrow cannot be taken away, or '' when it can: anything an AFTER
// draws, or an ORDERED parent chains, can be.
export function whyNotRemovable(to: GanttTask, readOnly?: boolean): string {
    if (readOnly) return 'Busy saving - try again in a moment';
    if (to.implied || !to.hash) return `${to.name} is not in this query, so it is not edited from here`;
    if (((to.props || {})['AFTER'] || '').trim() || to.chained) return '';
    return 'Nothing on this heading says it waits';
}
