// The words the query box suggests inside a function's brackets: keywords,
// tags, tag groups, property names and values, filters and collections.
//
// Asked for once per page load and shared by every query box, because they
// change only when the org files or the yaml do, and a box that fetched on
// every focus would be six requests per click. A request that fails leaves
// its part empty: a missing suggestion is the whole cost of it.

import * as React from 'react';
import { ODb } from './db';
import { QueryVocab, EMPTY_VOCAB } from './orgquery';

let shared: Promise<QueryVocab> | null = null;

async function settle<T>(p: Promise<T>, fallback: T): Promise<T> {
    try {
        const v = await p;
        return v == null ? fallback : v;
    } catch {
        return fallback;
    }
}

function load(): Promise<QueryVocab> {
    return Promise.all([
        settle(ODb.todoStates(), { Active: [], Done: [] }),
        settle(ODb.getAllTags(), [] as string[]),
        settle(ODb.getTagGroups(), {} as Record<string, string[]>),
        settle(ODb.getPropertyNames(), [] as { Name: string; Count: number; Values: string[] }[]),
        settle(ODb.getFilters(), {} as Record<string, string>),
        settle(ODb.recordCollections(), [] as { Type: string }[]),
    ]).then(([states, tags, groups, props, filters, cols]) => ({
        statuses: [...(states.Active || []), ...(states.Done || [])],
        tags: (Array.isArray(tags) ? tags : []).slice().sort((a, b) => a.localeCompare(b)),
        tagGroups: Object.keys(groups || {}).sort(),
        properties: (Array.isArray(props) ? props : []).map(p => ({
            name: p.Name, count: p.Count, values: p.Values || [],
        })),
        filters: Object.keys(filters || {}).sort().map(name => ({ name, query: filters[name] })),
        collections: (Array.isArray(cols) ? cols : []).map(c => c.Type).filter(Boolean),
    }));
}

// Forget what was fetched, so the next box to mount asks again - for after a
// change that adds a tag or a property.
export function refreshQueryVocab() {
    shared = null;
}

export default function useQueryVocab(): QueryVocab {
    const [vocab, setVocab] = React.useState<QueryVocab>(EMPTY_VOCAB);
    React.useEffect(() => {
        let alive = true;
        if (!shared) shared = load();
        const mine = shared;
        mine.then(v => {
            // Nothing at all came back - not logged in yet, or the server was
            // down - so the next box to mount asks again rather than every box
            // offering nothing until a reload.
            if (shared === mine && v.statuses.length + v.tags.length + v.properties.length === 0) shared = null;
            if (alive) setVocab(v);
        });
        return () => { alive = false; };
    }, []);
    return vocab;
}
