// The Drill tab: flashcards, drilled the way org-drill drills them.
//
// A deck is a query of your own - `HasTags("spanish")`, a saved search,
// anything the query language can say - and its cards are the headings it
// finds. Everything else is org-drill's: the card types, the [cloze] syntax,
// SM5/SM2/Simple8 scheduling, the 0-5 ratings, failed cards coming back until
// they are passed, leeches, cram mode, and the report at the end. The cards
// keep their DRILL_* properties in the file, so a deck can be drilled here and
// in Emacs by turns.
//
// The session logic is src/drill.ts (pure, tested); this file draws it.
// A session survives leaving the tab - to edit a card, say - and is offered
// back on return, like org-drill-resume.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Sheet from '@mui/joy/Sheet';
import Typography from '@mui/joy/Typography';
import Button from '@mui/joy/Button';
import IconButton from '@mui/joy/IconButton';
import Chip from '@mui/joy/Chip';
import Input from '@mui/joy/Input';
import Textarea from '@mui/joy/Textarea';
import Select from '@mui/joy/Select';
import Option from '@mui/joy/Option';
import Switch from '@mui/joy/Switch';
import FormControl from '@mui/joy/FormControl';
import FormLabel from '@mui/joy/FormLabel';
import FormHelperText from '@mui/joy/FormHelperText';
import Modal from '@mui/joy/Modal';
import ModalDialog from '@mui/joy/ModalDialog';
import ModalClose from '@mui/joy/ModalClose';
import Alert from '@mui/joy/Alert';
import List from '@mui/joy/List';
import ListItem from '@mui/joy/ListItem';
import ListItemButton from '@mui/joy/ListItemButton';
import ListItemContent from '@mui/joy/ListItemContent';
import Table from '@mui/joy/Table';
import Tooltip from '@mui/joy/Tooltip';
import CircularProgress from '@mui/joy/CircularProgress';
import Divider from '@mui/joy/Divider';
import LinearProgress from '@mui/joy/LinearProgress';
import AddIcon from '@mui/icons-material/Add';
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/DeleteOutline';
import PlayArrowIcon from '@mui/icons-material/PlayArrow';
import BoltIcon from '@mui/icons-material/Bolt';
import HelpOutlineIcon from '@mui/icons-material/HelpOutline';
import RefreshIcon from '@mui/icons-material/Refresh';
import StyleIcon from '@mui/icons-material/StyleOutlined';
import OpenInFileIcon from '@mui/icons-material/LaunchOutlined';

import { ODb } from '../db';
import ThemedHtml from './ThemedHtml';
import QueryBox from './QueryBox';
import { useNav } from '../NavContext';
import { useHtmlTheme } from '../useSettings';
import { isTyping } from './Capture';
import {
    DrillDeck, DrillCard, DrillCardsReply, Session, Presentation, Rng,
    newSession, nextCard, rate, skip as skipCard, pending, statusLetter, counters, clock,
    present, clozeHtml, CLOZE_CSS, report, duration, days, againSession, QUALITIES,
    deckSetting, DECK_DEFAULTS,
} from '../drill';

const rng: Rng = Math.random;

// The session in progress, kept outside the component so that leaving the tab
// and coming back finds it - the way org-drill-resume finds the session a quit
// or an edit left behind.
let live: { session: Session; reply: DrillCardsReply } | null = null;

const TONES: Record<string, 'primary' | 'success' | 'danger' | 'neutral' | 'warning'> = {
    new: 'primary', mature: 'success', failed: 'danger', neutral: 'neutral',
};

const STATUS_COLOR: Record<string, 'primary' | 'success' | 'danger' | 'neutral' | 'warning'> = {
    new: 'primary', failed: 'danger', overdue: 'warning', young: 'success', old: 'success',
    future: 'neutral', skipped: 'neutral',
};

// ── The tab ─────────────────────────────────────────────────────────────────

export default function Drill() {
    const theme = useHtmlTheme();
    const [decks, setDecks] = React.useState<DrillDeck[] | null>(null);
    const [selected, setSelected] = React.useState<string>('');
    const [editing, setEditing] = React.useState<{ deck: DrillDeck; index: number } | null>(null);
    const [help, setHelp] = React.useState(false);
    const [session, setSession] = React.useState<Session | null>(live?.session || null);
    const [reply, setReply] = React.useState<DrillCardsReply | null>(live?.reply || null);
    const [error, setError] = React.useState('');

    const loadDecks = React.useCallback(async () => {
        const ds = await ODb.getDrillDecks();
        setDecks(ds);
        setSelected(cur => (cur && ds.some(d => d.name === cur)) ? cur : (ds[0]?.name || ''));
    }, []);
    React.useEffect(() => { loadDecks(); }, [loadDecks]);

    async function saveDecks(next: DrillDeck[]) {
        const res = await ODb.saveDrillDecks(next);
        if (res && res.Ok === false) {
            setError(res.Msg);
            return false;
        }
        setError('');
        setDecks(next);
        return true;
    }

    async function start(deck: DrillDeck, cram: boolean) {
        const r = await ODb.getDrillCards({ deck: deck.name, cram, theme });
        if (!r || !r.ok) {
            setError(r?.msg || 'could not read the deck');
            return;
        }
        const s = newSession(r, cram, Date.now(), rng);
        live = { session: s, reply: r };
        setReply(r);
        setSession(s);
    }

    function finish() {
        live = null;
        setSession(null);
        setReply(null);
    }

    if (session && reply) {
        return <SessionView session={session} reply={reply} onEnd={finish}
            onAgain={() => { const s = againSession(session, Date.now()); live = { session: s, reply }; setSession(s); }} />;
    }

    const deck = decks?.find(d => d.name === selected) || null;
    return (
        <Box sx={{ display: 'flex', gap: 2, alignItems: 'flex-start', flexWrap: { xs: 'wrap', md: 'nowrap' } }}>
            <Sheet variant="outlined" sx={{ borderRadius: 'md', width: { xs: '100%', md: 260 }, flexShrink: 0, p: 1 }}>
                <Box sx={{ display: 'flex', alignItems: 'center', px: 1, py: 0.5 }}>
                    <Typography level="title-sm" sx={{ flex: 1 }}>Decks</Typography>
                    <Tooltip title="How flashcards work"><IconButton size="sm" onClick={() => setHelp(true)}><HelpOutlineIcon /></IconButton></Tooltip>
                    <Tooltip title="New deck">
                        <IconButton size="sm" onClick={() => setEditing({ deck: { name: '', query: '' }, index: -1 })}><AddIcon /></IconButton>
                    </Tooltip>
                </Box>
                {decks === null ? <CircularProgress size="sm" sx={{ m: 2 }} /> : decks.length === 0 ? (
                    <Typography level="body-sm" sx={{ p: 1.5, color: 'text.tertiary' }}>
                        No decks yet. A deck is a query: the headings it finds are its cards.
                    </Typography>
                ) : (
                    <List size="sm">
                        {decks.map(d => (
                            <ListItem key={d.name}>
                                <ListItemButton selected={d.name === selected} onClick={() => setSelected(d.name)}>
                                    <StyleIcon fontSize="small" />
                                    <ListItemContent>
                                        <Typography level="title-sm">{d.name}</Typography>
                                        <Typography level="body-xs" noWrap sx={{ fontFamily: 'monospace' }}>
                                            {d.storedQuery ? `saved: ${d.storedQuery}` : d.query}
                                        </Typography>
                                    </ListItemContent>
                                </ListItemButton>
                            </ListItem>
                        ))}
                    </List>
                )}
                {live && (
                    <Button fullWidth size="sm" variant="soft" color="success" sx={{ mt: 1 }}
                        onClick={() => { setReply(live!.reply); setSession(live!.session); }}>
                        Resume session
                    </Button>
                )}
            </Sheet>
            <Box sx={{ flex: 1, minWidth: 0 }}>
                {error && <Alert color="danger" sx={{ mb: 1 }}>{error}</Alert>}
                {deck ? (
                    <DeckView key={deck.name} deck={deck} theme={theme}
                        onStart={cram => start(deck, cram)}
                        onEdit={() => setEditing({ deck, index: decks!.indexOf(deck) })}
                        onDelete={async () => {
                            if (window.confirm(`Delete the deck "${deck.name}"? Its cards and their history stay in your files.`)) {
                                await saveDecks(decks!.filter(d => d !== deck));
                            }
                        }} />
                ) : decks && decks.length === 0 ? <Welcome onNew={() => setEditing({ deck: { name: '', query: 'HasTags("drill")' }, index: -1 })} onHelp={() => setHelp(true)} /> : null}
            </Box>
            {editing && (
                <DeckEditor initial={editing.deck} names={(decks || []).filter((_, i) => i !== editing.index).map(d => d.name)}
                    onClose={() => setEditing(null)}
                    onSave={async d => {
                        const next = (decks || []).slice();
                        if (editing.index >= 0) next[editing.index] = d; else next.push(d);
                        if (await saveDecks(next)) {
                            setSelected(d.name);
                            setEditing(null);
                        }
                    }} />
            )}
            <HelpDialog open={help} onClose={() => setHelp(false)} />
        </Box>
    );
}

function Welcome(props: { onNew: () => void; onHelp: () => void }) {
    return (
        <Sheet variant="soft" sx={{ borderRadius: 'md', p: 3 }}>
            <Typography level="h4" sx={{ mb: 1 }}>Flashcards from your notes</Typography>
            <Typography level="body-md" sx={{ mb: 1 }}>
                Any heading can be a flashcard. Its body is the question; its child headings are the answer.
                Write <code>[hidden words]</code> in a body to make a cloze.
            </Typography>
            <Typography level="body-md" sx={{ mb: 2 }}>
                A deck is a query - <code>HasTags("spanish")</code>, a saved search, anything - so one set of notes can hold
                as many decks as you like. Reviews are scheduled exactly as Emacs' org-drill schedules them, and written
                into the same properties, so both can drill the same cards.
            </Typography>
            <Box sx={{ display: 'flex', gap: 1 }}>
                <Button startDecorator={<AddIcon />} onClick={props.onNew}>Make a deck</Button>
                <Button variant="plain" onClick={props.onHelp}>How it works</Button>
            </Box>
        </Sheet>
    );
}

// ── One deck ────────────────────────────────────────────────────────────────

function DeckView(props: { deck: DrillDeck; theme: string; onStart: (cram: boolean) => void; onEdit: () => void; onDelete: () => void }) {
    const { deck } = props;
    const nav = useNav();
    const [reply, setReply] = React.useState<DrillCardsReply | null>(null);
    const [loading, setLoading] = React.useState(false);
    const [browse, setBrowse] = React.useState(false);

    const load = React.useCallback(async () => {
        setLoading(true);
        setReply(await ODb.getDrillCards({ deck: deck.name, theme: props.theme }));
        setLoading(false);
    }, [deck.name, props.theme]);
    React.useEffect(() => { load(); }, [load]);

    const c = reply?.counts;
    const due = c ? c.new + c.failed + c.overdue + c.young + c.old : 0;
    const leeches = (reply?.cards || []).filter(x => x.leech).length;
    return (
        <Sheet variant="outlined" sx={{ borderRadius: 'md', p: 2 }}>
            <Box sx={{ display: 'flex', alignItems: 'flex-start', gap: 1, mb: 1 }}>
                <Box sx={{ flex: 1, minWidth: 0 }}>
                    <Typography level="h3">{deck.name}</Typography>
                    {deck.description && <Typography level="body-md" sx={{ color: 'text.secondary' }}>{deck.description}</Typography>}
                    <Typography level="body-xs" sx={{ fontFamily: 'monospace', mt: 0.5 }}>
                        {deck.storedQuery ? `saved search: ${deck.storedQuery}` : deck.query}
                        {'  ·  '}{deckSetting(deck, 'algorithm').toUpperCase()}
                    </Typography>
                </Box>
                <Tooltip title="Count again"><IconButton size="sm" onClick={load}><RefreshIcon /></IconButton></Tooltip>
                <Tooltip title="Edit deck"><IconButton size="sm" onClick={props.onEdit}><EditIcon /></IconButton></Tooltip>
                <Tooltip title="Delete deck"><IconButton size="sm" color="danger" onClick={props.onDelete}><DeleteIcon /></IconButton></Tooltip>
            </Box>
            {loading && !reply ? <CircularProgress size="sm" /> : reply && !reply.ok ? (
                <Alert color="danger">{reply.msg}</Alert>
            ) : c ? (
                <>
                    <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', my: 2 }}>
                        <Stat label="due now" value={due} color="primary" big />
                        <Stat label="new" value={c.new} color="primary" />
                        <Stat label="failed" value={c.failed} color="danger" />
                        <Stat label="overdue" value={c.overdue} color="warning" />
                        <Stat label="young" value={c.young} color="success" />
                        <Stat label="old" value={c.old} color="success" />
                        <Stat label="not yet due" value={c.future} color="neutral" />
                        <Stat label="due tomorrow" value={c.dueTomorrow} color="neutral" />
                        {(c.skipped > 0 || leeches > 0) && <Stat label="leeches" value={leeches} color="danger" />}
                    </Box>
                    <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
                        <Button size="lg" startDecorator={<PlayArrowIcon />} disabled={due === 0} onClick={() => props.onStart(false)}>
                            {due === 0 ? 'Nothing due' : `Drill ${Math.min(due, deckSetting(deck, 'maxItems') > 0 ? deckSetting(deck, 'maxItems') : due)} of ${due}`}
                        </Button>
                        <Tooltip title={`Cram: everything not seen in the last ${deckSetting(deck, 'cramHours')} hours, with no limits. Nothing is rescheduled.`}>
                            <Button size="lg" variant="soft" startDecorator={<BoltIcon />} disabled={c.total === 0} onClick={() => props.onStart(true)}>Cram</Button>
                        </Tooltip>
                        <Button size="lg" variant="plain" onClick={() => setBrowse(b => !b)}>{browse ? 'Hide cards' : `Browse ${c.total} cards`}</Button>
                    </Box>
                    {reply!.problems && reply!.problems.length > 0 && (
                        <Alert color="warning" variant="soft" sx={{ mt: 2, display: 'block' }}>
                            <Typography level="title-sm">{reply!.problems.length} heading{reply!.problems.length === 1 ? '' : 's'} left out</Typography>
                            {reply!.problems.slice(0, 8).map(p => <Typography key={p} level="body-xs">{p}</Typography>)}
                        </Alert>
                    )}
                    {browse && <CardTable cards={reply!.cards || []} onOpen={card => nav.toFile({
                        filename: card.file, line: card.line - 1, heading: card.name,
                        back: { app: 'Drill', label: 'Back to flashcards' },
                    })} />}
                </>
            ) : null}
        </Sheet>
    );
}

function Stat(props: { label: string; value: number; color: 'primary' | 'success' | 'danger' | 'neutral' | 'warning'; big?: boolean }) {
    return (
        <Sheet variant="soft" color={props.color} sx={{ borderRadius: 'md', px: 1.5, py: 1, minWidth: props.big ? 110 : 80, textAlign: 'center' }}>
            <Typography level={props.big ? 'h2' : 'h4'} color={props.color}>{props.value}</Typography>
            <Typography level="body-xs">{props.label}</Typography>
        </Sheet>
    );
}

function CardTable(props: { cards: DrillCard[]; onOpen: (c: DrillCard) => void }) {
    const sorted = props.cards.slice().sort((a, b) => (a.scheduled || '').localeCompare(b.scheduled || ''));
    return (
        <Table size="sm" stickyHeader hoverRow sx={{ mt: 2, '& td': { verticalAlign: 'top' } }}>
            <thead>
                <tr>
                    <th style={{ width: '38%' }}>Card</th><th>Type</th><th>Status</th><th>Next review</th>
                    <th>Ease</th><th>Reviews</th><th>Failures</th><th style={{ width: 40 }} />
                </tr>
            </thead>
            <tbody>
                {sorted.map(c => (
                    <tr key={c.hash}>
                        <td>{c.name}{c.leech && <Chip size="sm" color="danger" sx={{ ml: 1 }}>leech</Chip>}</td>
                        <td><Typography level="body-xs">{c.type}</Typography></td>
                        <td><Chip size="sm" variant="soft" color={STATUS_COLOR[c.status]}>{c.status === 'future' ? 'not due' : c.status}</Chip></td>
                        <td>{c.scheduled || '—'}</td>
                        <td>{c.data.ease !== undefined && c.data.ease !== null ? c.data.ease.toFixed(2) : '—'}</td>
                        <td>{c.data.totalRepeats}</td>
                        <td>{c.data.failures}</td>
                        <td><Tooltip title="Open in the file"><IconButton size="sm" onClick={() => props.onOpen(c)}><OpenInFileIcon /></IconButton></Tooltip></td>
                    </tr>
                ))}
            </tbody>
        </Table>
    );
}

// ── Making and changing a deck ──────────────────────────────────────────────

function DeckEditor(props: { initial: DrillDeck; names: string[]; onClose: () => void; onSave: (d: DrillDeck) => void }) {
    const [d, setD] = React.useState<DrillDeck>({ ...props.initial });
    const [saved, setSaved] = React.useState<{ name: string; query: string }[]>([]);
    const [preview, setPreview] = React.useState<DrillCardsReply | null>(null);
    const [checking, setChecking] = React.useState(false);
    React.useEffect(() => { ODb.getStoredQueries().then(qs => setSaved(Array.isArray(qs) ? qs : [])); }, []);
    const set = (patch: Partial<DrillDeck>) => setD(cur => ({ ...cur, ...patch }));
    const num = (k: keyof typeof DECK_DEFAULTS) => (d as any)[k] ?? '';
    const nameTaken = props.names.includes(d.name.trim());
    const query = d.storedQuery ? (saved.find(q => q.name === d.storedQuery)?.query || '') : (d.query || '');
    const valid = d.name.trim() !== '' && !nameTaken && query.trim() !== '';

    async function check() {
        setChecking(true);
        setPreview(await ODb.getDrillCards({ query }));
        setChecking(false);
    }

    const numField = (k: keyof typeof DECK_DEFAULTS, label: string, help: string, step = 1) => (
        <FormControl size="sm">
            <FormLabel>{label}</FormLabel>
            <Input type="number" slotProps={{ input: { step } }} value={num(k)} placeholder={String(DECK_DEFAULTS[k])}
                onChange={e => set({ [k]: e.target.value === '' ? undefined : Number(e.target.value) } as any)} />
            <FormHelperText>{help}</FormHelperText>
        </FormControl>
    );
    const toggle = (k: keyof DrillDeck, label: string, help: string) => (
        <FormControl size="sm" orientation="horizontal" sx={{ justifyContent: 'space-between', gap: 2 }}>
            <Box><FormLabel>{label}</FormLabel><FormHelperText>{help}</FormHelperText></Box>
            <Switch checked={!!(d as any)[k]} onChange={e => set({ [k]: e.target.checked } as any)} />
        </FormControl>
    );

    return (
        <Modal open onClose={props.onClose}>
            <ModalDialog sx={{ width: 'min(760px, 96vw)', maxHeight: '92vh', overflow: 'auto' }}>
                <ModalClose />
                <Typography level="h4" sx={{ mb: 1 }}>{props.initial.name ? `Deck: ${props.initial.name}` : 'New deck'}</Typography>
                <Box>
                    <Box sx={{ display: 'grid', gap: 1.5 }}>
                        <FormControl error={nameTaken}>
                            <FormLabel>Name</FormLabel>
                            <Input autoFocus value={d.name} onChange={e => set({ name: e.target.value })} placeholder="Spanish vocabulary" />
                            {nameTaken && <FormHelperText>Another deck has that name.</FormHelperText>}
                        </FormControl>
                        <FormControl>
                            <FormLabel>Description</FormLabel>
                            <Textarea minRows={1} value={d.description || ''} onChange={e => set({ description: e.target.value })} />
                        </FormControl>
                        <FormControl>
                            <FormLabel>Cards are the headings found by</FormLabel>
                            <Select size="sm" value={d.storedQuery ? 'saved' : 'query'}
                                onChange={(_, v) => set(v === 'saved' ? { storedQuery: saved[0]?.name || '' } : { storedQuery: '' })}>
                                <Option value="query">this query</Option>
                                <Option value="saved" disabled={saved.length === 0}>a saved search</Option>
                            </Select>
                        </FormControl>
                        {d.storedQuery !== undefined && d.storedQuery !== '' ? (
                            <FormControl>
                                <Select value={d.storedQuery} onChange={(_, v) => set({ storedQuery: v || '' })}>
                                    {saved.map(q => <Option key={q.name} value={q.name}>{q.name}</Option>)}
                                </Select>
                                <FormHelperText sx={{ fontFamily: 'monospace' }}>{query}</FormHelperText>
                            </FormControl>
                        ) : (
                            <FormControl>
                                <QueryBox value={d.query || ''} onChange={v => set({ query: v })} placeholder='HasTags("spanish")' onEnter={check} />
                                <FormHelperText>
                                    A heading found whose parent was also found is part of that card (an answer or a side).
                                    A found heading with nothing in it, over found headings, just groups them.
                                </FormHelperText>
                            </FormControl>
                        )}
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                            <Button size="sm" variant="outlined" loading={checking} disabled={!query.trim()} onClick={check}>Check the query</Button>
                            {preview && (preview.ok
                                ? <Typography level="body-sm">{preview.counts.total} cards ({preview.counts.new} new){preview.problems?.length ? `, ${preview.problems.length} left out` : ''}</Typography>
                                : <Typography level="body-sm" color="danger">{preview.msg}</Typography>)}
                        </Box>

                        <Divider sx={{ my: 1 }}>Scheduling</Divider>
                        <FormControl size="sm">
                            <FormLabel>Algorithm</FormLabel>
                            <Select value={d.algorithm || 'sm5'} onChange={(_, v) => set({ algorithm: v || 'sm5' })}>
                                <Option value="sm5">SM5 - learns how you forget (org-drill's default)</Option>
                                <Option value="sm2">SM2 - Anki's ancestor: 1 day, 6 days, then by ease</Option>
                                <Option value="simple8">Simple8 - from your average quality alone</Option>
                            </Select>
                        </FormControl>
                        <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', sm: '1fr 1fr' }, gap: 1.5 }}>
                            {numField('maxItems', 'Cards per session', 'Stop after this many are passed. -1 for no limit.')}
                            {numField('maxMinutes', 'Minutes per session', 'Stop after this long. -1 for no limit.')}
                            {numField('failureQuality', 'Failure quality', 'A rating at or below this is a failure. 1 is Mnemosyne-like.')}
                            {numField('learnFraction', 'Learn fraction', 'How fast intervals grow (SM5, Simple8). Lower for more reviews.', 0.05)}
                            {numField('leechThreshold', 'Leech after failures', 'A card failed more often is tagged leech.')}
                            <FormControl size="sm">
                                <FormLabel>Leeches</FormLabel>
                                <Select value={d.leechMethod || 'skip'} onChange={(_, v) => set({ leechMethod: v || 'skip' })}>
                                    <Option value="skip">skip them</Option>
                                    <Option value="warn">ask them, with a warning</Option>
                                    <Option value="none">ask them as usual</Option>
                                </Select>
                                <FormHelperText>A leech wants rewriting, not more drilling.</FormHelperText>
                            </FormControl>
                            {numField('daysBeforeOld', 'Days before old', 'A card with a longer interval counts as old, not young.')}
                            {numField('overdueFactor', 'Overdue factor', 'How late, as a share of the interval, counts as overdue.', 0.1)}
                            {numField('forgettingIndex', 'Forgetting index', 'Warn when more than this % of a session is failed.')}
                            {numField('cramHours', 'Cram hours', 'Cram asks what was not seen in this many hours.')}
                        </Box>
                        {toggle('countFailed', 'Failed cards count toward the limit', 'org-drill-item-count-includes-failed-items-p')}
                        {toggle('noise', 'Spread reviews out', 'A little randomness on each interval, so cards learnt together are not always due together.')}
                        {toggle('lapseOverdue', 'Forget very overdue cards', 'A card over 90 days overdue is treated as forgotten.')}

                        <Divider sx={{ my: 1 }}>Showing cards</Divider>
                        {toggle('hideTitles', 'Hide headings', 'For cards whose heading gives the answer away.')}
                        {toggle('typedAnswers', 'Type the answer', 'Type before you look; your answer is shown beside the real one.')}
                        {toggle('clozeLengthDots', 'Clozes show their length', '[.....] with a dot per hidden letter, instead of [...].')}
                    </Box>
                </Box>
                <Box sx={{ display: 'flex', justifyContent: 'flex-end', gap: 1, mt: 1 }}>
                    <Button variant="plain" onClick={props.onClose}>Cancel</Button>
                    <Button disabled={!valid} onClick={() => props.onSave({ ...d, name: d.name.trim() })}>Save deck</Button>
                </Box>
            </ModalDialog>
        </Modal>
    );
}

// ── Drilling ────────────────────────────────────────────────────────────────

type Phase = 'question' | 'answer' | 'report' | 'warning';

function SessionView(props: { session: Session; reply: DrillCardsReply; onEnd: () => void; onAgain: () => void }) {
    const { session: s, reply } = props;
    const deck = reply.deck;
    const nav = useNav();
    const [hash, setHash] = React.useState<string | null>(s.current);
    const [phase, setPhase] = React.useState<Phase>('question');
    const [pres, setPres] = React.useState<Presentation | null>(null);
    const [typed, setTyped] = React.useState('');
    const [busy, setBusy] = React.useState(false);
    const [note, setNote] = React.useState('');
    const [helpOpen, setHelpOpen] = React.useState(false);
    const [, tick] = React.useState(0);
    const typedRef = React.useRef<HTMLTextAreaElement | null>(null);

    // The clock, redrawn every second as org-drill's prompt is.
    React.useEffect(() => {
        const t = window.setInterval(() => tick(x => x + 1), 1000);
        return () => window.clearInterval(t);
    }, []);

    const advance = React.useCallback(() => {
        const h = nextCard(s, Date.now(), rng);
        setHash(h);
        setTyped('');
        if (h === null) {
            setPhase('report');
            setPres(null);
            return;
        }
        setPres(present(s.cards[h], rng));
        setPhase('question');
    }, [s]);

    // On the way in: carry on with the card that was up, or take the next.
    React.useEffect(() => {
        if (s.current) {
            setPres(present(s.cards[s.current], rng));
            setHash(s.current);
        } else {
            advance();
        }
    }, []);

    const card = hash ? s.cards[hash] : null;

    async function rateCard(q: number) {
        if (!card || busy) return;
        setBusy(true);
        if (!s.cram) {
            const res = await ODb.drillReview(card.hash, q, deck.name);
            if (!res || !res.ok) {
                setNote(`Not saved: ${res?.msg || 'no answer from the server'}`);
                setBusy(false);
                return;
            }
            setNote(res.leech ? `${res.msg}. This card is now a leech.` : res.msg);
        } else {
            setNote('');
        }
        rate(s, card.hash, q, rng);
        setBusy(false);
        advance();
    }

    function edit() {
        if (!card) return;
        // The session stays where it is; coming back offers it again.
        nav.toFile({ filename: card.file, line: card.line - 1, heading: card.name, back: { app: 'Drill', label: 'Back to the drill' } });
    }

    function quit() {
        // Ratings already given are in the files; what is left can be resumed.
        props.onEnd();
    }

    // Keys: any key shows the answer, 0-5 rate it, e edits, s skips, q quits.
    React.useEffect(() => {
        const onKey = (e: KeyboardEvent) => {
            if (e.metaKey || e.ctrlKey || e.altKey || helpOpen) return;
            if (isTyping(e.target)) {
                if (e.key === 'Enter' && !e.shiftKey && phase === 'question') { e.preventDefault(); setPhase('answer'); }
                return;
            }
            if (document.querySelector('.MuiModal-root')) return;
            const k = e.key;
            if (phase === 'question') {
                if (k === 'q' || k === 'Escape') { e.preventDefault(); quit(); return; }
                if (k === 'e') { e.preventDefault(); edit(); return; }
                if (k === 's') { e.preventDefault(); skipCard(s); advance(); return; }
                if (k.length === 1 || k === 'Enter') { e.preventDefault(); setPhase('answer'); }
            } else if (phase === 'answer') {
                if (k >= '0' && k <= '5') { e.preventDefault(); rateCard(Number(k)); return; }
                if (k === '?') { e.preventDefault(); setHelpOpen(true); return; }
                if (k === 'e') { e.preventDefault(); edit(); return; }
                if (k === 'q' || k === 'Escape') { e.preventDefault(); quit(); }
            } else if (phase === 'report' && (k === 'Enter' || k === ' ' || k === 'Escape')) {
                e.preventDefault();
                const r = report(s, Date.now());
                if (r.warn) setPhase('warning'); else props.onEnd();
            } else if (phase === 'warning' && (k === 'Enter' || k === ' ' || k === 'Escape')) {
                e.preventDefault();
                props.onEnd();
            }
        };
        window.addEventListener('keydown', onKey);
        return () => window.removeEventListener('keydown', onKey);
    });

    React.useEffect(() => {
        if (phase === 'question' && deck.typedAnswers) typedRef.current?.focus();
    }, [phase, hash, deck.typedAnswers]);

    if (phase === 'report' || phase === 'warning') {
        return <ReportView session={s} warning={phase === 'warning'} onDone={() => {
            if (phase === 'report' && report(s, Date.now()).warn) setPhase('warning'); else props.onEnd();
        }} onAgain={pending(s) > 0 ? props.onAgain : undefined} />;
    }
    if (!card || !pres) return <CircularProgress />;

    const cnt = counters(s);
    const letter = statusLetter(s, card);
    const answer = phase === 'answer';
    const hide = answer ? 'none' as const : pres.hide;
    const dots = !!deck.clozeLengthDots;
    const sides = card.sides || [];
    const elapsed = Date.now() - s.start;
    const maxMin = deckSetting(deck, 'maxMinutes');
    const leechWarn = card.leech && deck.leechMethod === 'warn';

    // What is drawn: the title (unless hidden or replaced), the body (or the
    // generated prompt), and the sides - folded to their titles in the
    // question, except the side being asked; opened in the answer, except a
    // side that is itself a card.
    let html = '';
    const showTitle = !(deck.hideTitles && !answer);
    if (answer && pres.answerHeading) {
        html += `<h2>${escapeHtml(pres.answerHeading)}</h2>`;
    } else if (showTitle) {
        html += `<h2>${clozeHtml(card.title, hide, dots)}</h2>`;
    }
    if (pres.prompt && !answer) {
        html += pres.prompt.split('\n\n').map(p => `<p>${escapeHtml(p)}</p>`).join('');
    } else {
        html += clozeHtml(card.body, hide, dots);
    }
    sides.forEach((side, i) => {
        const open = answer ? !side.isCard : i === pres.side;
        html += `<h3>${clozeHtml(side.title, hide, dots)}</h3>`;
        if (open) html += clozeHtml(side.body, hide, dots);
    });
    if (answer && card.explain && card.explain.length) {
        html += `<h3>Explanation</h3>${card.explain.join('')}`;
    }

    return (
        <Box sx={{ maxWidth: 900, width: '100%', mx: 'auto' }}>
            {/* The prompt line: clock, status letter, done / failed / mature / new. */}
            <Sheet variant="soft" sx={{ borderRadius: 'md', px: 2, py: 1, mb: 1.5, display: 'flex', alignItems: 'center', gap: 1.5, flexWrap: 'wrap' }}>
                <Typography level="title-md" sx={{ fontFamily: 'monospace' }}>{clock(elapsed)}</Typography>
                <Tooltip title={{ F: 'failed', C: 'cram', N: 'new', Y: 'young', o: 'old', '!': 'overdue' }[letter.letter] || ''}>
                    <Chip variant="solid" color={TONES[letter.tone]} sx={{ fontFamily: 'monospace', fontWeight: 700 }}>{letter.letter}</Chip>
                </Tooltip>
                <Tooltip title="done"><Chip variant="soft" color="warning">{cnt.done}</Chip></Tooltip>
                <Tooltip title="failed"><Chip variant="soft" color="danger">{cnt.failed}</Chip></Tooltip>
                <Tooltip title="young, old and overdue"><Chip variant="soft" color="success">{cnt.mature}</Chip></Tooltip>
                <Tooltip title="new"><Chip variant="soft" color="primary">{cnt.fresh}</Chip></Tooltip>
                <Box sx={{ flex: 1 }} />
                <Typography level="body-sm" sx={{ color: 'text.secondary' }}>{deck.name}{s.cram ? ' · cram' : ''}</Typography>
                <Button size="sm" variant="plain" color="neutral" onClick={quit}>Quit (q)</Button>
            </Sheet>
            {!s.cram && maxMin > 0 && (
                <LinearProgress determinate value={Math.min(100, 100 * Math.max(elapsed / (maxMin * 60000), s.done.length / Math.max(1, deckSetting(deck, 'maxItems'))))}
                    sx={{ mb: 1.5 }} size="sm" />
            )}
            {leechWarn && (
                <Alert color="danger" variant="soft" sx={{ mb: 1.5 }}>
                    <Box>
                        <Typography level="title-sm">!!! LEECH ITEM !!!</Typography>
                        <Typography level="body-sm">You seem to be having a lot of trouble memorising this item. Consider reformulating the item to make it easier to remember.</Typography>
                    </Box>
                </Alert>
            )}
            <Sheet variant="outlined" sx={{ borderRadius: 'lg', p: { xs: 2, sm: 4 }, minHeight: 260, boxShadow: 'sm' }}>
                <ThemedHtml html={html} style={reply.style} extraCss={CLOZE_CSS}
                    sx={{ fontSize: '18px', '& .drill-hidden': { fontWeight: 600, color: 'warning.plainColor' }, '& .drill-shown': { bgcolor: 'warning.softBg', borderRadius: '3px', px: 0.25 }, '& h2': { mt: 0 } }} />
                {deck.typedAnswers && (
                    phase === 'question' ? (
                        <Textarea slotProps={{ textarea: { ref: typedRef } }} minRows={2} sx={{ mt: 2 }} value={typed}
                            onChange={e => setTyped(e.target.value)} placeholder="Type your answer and press Enter" />
                    ) : typed.trim() ? (
                        <Sheet variant="soft" color="neutral" sx={{ mt: 2, p: 1.5, borderRadius: 'sm' }}>
                            <Typography level="body-xs">Your answer</Typography>
                            <Typography sx={{ whiteSpace: 'pre-wrap' }}>{typed}</Typography>
                        </Sheet>
                    ) : null
                )}
            </Sheet>

            {phase === 'question' ? (
                <Box sx={{ display: 'flex', gap: 1, mt: 2, alignItems: 'center', flexWrap: 'wrap' }}>
                    <Button size="lg" onClick={() => setPhase('answer')}>Show answer</Button>
                    <Typography level="body-sm" sx={{ color: 'text.tertiary' }}>any key</Typography>
                    <Box sx={{ flex: 1 }} />
                    <Button variant="plain" color="neutral" onClick={edit}>Edit (e)</Button>
                    <Button variant="plain" color="neutral" onClick={() => { skipCard(s); advance(); }}>Skip (s)</Button>
                </Box>
            ) : (
                <Box sx={{ mt: 2 }}>
                    <Typography level="body-sm" sx={{ mb: 1, color: 'text.secondary' }}>How well did you do? (0-5, ? for help)</Typography>
                    <Box sx={{ display: 'grid', gridTemplateColumns: { xs: 'repeat(3, 1fr)', sm: 'repeat(6, 1fr)' }, gap: 1 }}>
                        {QUALITIES.map(({ q, label }) => {
                            const fail = q <= deckSetting(deck, 'failureQuality');
                            return (
                                <Tooltip key={q} title={QUALITIES[q].meaning}>
                                    <Button variant={fail ? 'soft' : 'solid'} color={fail ? 'danger' : q === 3 ? 'warning' : 'success'}
                                        disabled={busy} onClick={() => rateCard(q)} sx={{ flexDirection: 'column', py: 1 }}>
                                        <Typography level="title-lg" sx={{ color: 'inherit' }}>{q}</Typography>
                                        <Typography level="body-xs" sx={{ color: 'inherit' }}>{label}</Typography>
                                        <Typography level="body-xs" sx={{ color: 'inherit', opacity: 0.8 }}>
                                            {s.cram ? '' : fail ? 'again' : days(card.next[q])}
                                        </Typography>
                                    </Button>
                                </Tooltip>
                            );
                        })}
                    </Box>
                    <Box sx={{ display: 'flex', mt: 1 }}>
                        <Box sx={{ flex: 1 }} />
                        <Button variant="plain" color="neutral" onClick={edit}>Edit (e)</Button>
                        <Button variant="plain" color="neutral" onClick={() => setHelpOpen(true)}>Help (?)</Button>
                    </Box>
                </Box>
            )}
            {note && <Typography level="body-xs" sx={{ mt: 1, color: 'text.tertiary' }}>{note}</Typography>}
            <Modal open={helpOpen} onClose={() => setHelpOpen(false)}>
                <ModalDialog>
                    <ModalClose />
                    <Typography level="h4" sx={{ mb: 1 }}>How well did you do?</Typography>
                    <Typography level="body-sm">0-{deckSetting(deck, 'failureQuality')} means you have forgotten the item. {deckSetting(deck, 'failureQuality') + 1}-5 means you have remembered it.</Typography>
                    {QUALITIES.map(({ q, meaning }) => (
                        <Typography key={q} level="body-sm"><b>{q}</b> - {meaning}{q > deckSetting(deck, 'failureQuality') && !s.cram ? ` (${days(card.next[q])})` : ''}</Typography>
                    ))}
                </ModalDialog>
            </Modal>
        </Box>
    );
}

function escapeHtml(s: string): string {
    return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// ── The end of a session ────────────────────────────────────────────────────

function ReportView(props: { session: Session; warning: boolean; onDone: () => void; onAgain?: () => void }) {
    const r = report(props.session, Date.now());
    const row = (a: [string, number], b: [string, number]) => (
        <tr><td>{a[0]}</td><td style={{ textAlign: 'right' }}>{r.percent[a[1]]}%</td><td style={{ width: 24 }} /><td>{b[0]}</td><td style={{ textAlign: 'right' }}>{r.percent[b[1]]}%</td></tr>
    );
    return (
        <Sheet variant="outlined" sx={{ borderRadius: 'lg', p: 3, maxWidth: 640, mx: 'auto' }}>
            {props.warning ? (
                <>
                    <Typography level="h3" color="danger" sx={{ mb: 1 }}>WARNING!</Typography>
                    <Typography sx={{ mb: 1 }}>You failed {100 - r.passPercent}% of the items you reviewed during this session.</Typography>
                    <Typography sx={{ mb: 1 }}>{r.overdueAtStart} ({r.overduePercent}%) of all items scanned were overdue.</Typography>
                    <Typography sx={{ mb: 2 }}>
                        Are you keeping up with your items, and reviewing them when they are scheduled? If so, you may want to
                        consider lowering the deck's learn fraction slightly in order to make items appear more frequently over time.
                    </Typography>
                    <Button onClick={props.onDone}>Done</Button>
                </>
            ) : (
                <>
                    <Typography level="h3" sx={{ mb: 1 }}>Session finished</Typography>
                    <Typography sx={{ mb: 1.5 }}>{r.reviewed} items reviewed. Session duration {duration(r.seconds)}.</Typography>
                    {props.session.qualities.length > 0 && (
                        <>
                            <Typography level="title-sm">Recall of reviewed items:</Typography>
                            <Table size="sm" borderAxis="none" sx={{ my: 1, maxWidth: 480 }}>
                                <tbody>
                                    {row(['Excellent (5)', 5], ['Near miss (2)', 2])}
                                    {row(['Good (4)', 4], ['Failure (1)', 1])}
                                    {row(['Hard (3)', 3], ['Abject failure (0)', 0])}
                                </tbody>
                            </Table>
                            <Typography sx={{ mb: 1 }}>You successfully recalled {r.passPercent}% of reviewed items (quality &gt; {r.failureQuality})</Typography>
                        </>
                    )}
                    <Typography sx={{ mb: 1 }}>
                        {r.pending}/{r.pendingAll} items still await review ({r.failed} failed, {r.overdue} overdue, {r.fresh} new, {r.young} young, {r.old} old).
                    </Typography>
                    <Typography sx={{ mb: 2 }}>Tomorrow, {r.dueTomorrow} more items will become due for review.</Typography>
                    <Box sx={{ display: 'flex', gap: 1 }}>
                        <Button onClick={props.onDone}>Done</Button>
                        {props.onAgain && <Button variant="soft" onClick={props.onAgain}>Keep going ({r.pending} left)</Button>}
                    </Box>
                </>
            )}
        </Sheet>
    );
}

// ── Help ────────────────────────────────────────────────────────────────────

function HelpDialog(props: { open: boolean; onClose: () => void }) {
    const code = (s: string) => <Box component="pre" sx={{ bgcolor: 'background.level1', p: 1, borderRadius: 'sm', fontSize: '12px', overflow: 'auto', my: 1 }}>{s}</Box>;
    return (
        <Modal open={props.open} onClose={props.onClose}>
            <ModalDialog sx={{ width: 'min(780px, 96vw)', maxHeight: '92vh', overflow: 'auto' }}>
                <ModalClose />
                <Typography level="h4" sx={{ mb: 1 }}>Flashcards</Typography>
                <Box>
                    <Typography level="body-md">
                        A card is a heading. Its body is the question; its child headings are the answer. A deck is a query, and
                        every heading it finds is a card - so <code>HasTags("spanish")</code> and <code>HasTags("chemistry")</code>{' '}
                        are two decks in the same notes. Scheduling, card types and the properties written are Emacs org-drill's,
                        so cards can be drilled here and in Emacs by turns.
                    </Typography>
                    <Typography level="title-md" sx={{ mt: 2 }}>A simple card</Typography>
                    {code(`* What is the capital of France?          :geography:
** Answer
Paris`)}
                    <Typography level="title-md">Clozes</Typography>
                    <Typography level="body-sm">Square brackets hide words; <code>||</code> adds a hint. Checkboxes, cookies, dates, footnotes and links are not clozes.</Typography>
                    {code(`* Spain                                    :geography:
The capital of Spain is [Madrid||starts with M].`)}
                    <Typography level="title-md">Card types</Typography>
                    <Typography level="body-sm">Set with a <code>:DRILL_CARD_TYPE:</code> property, on the card or on a heading above it.</Typography>
                    <Table size="sm" sx={{ my: 1 }}>
                        <tbody>
                            {[
                                ['simple', 'the body is asked, every cloze hidden (the default)'],
                                ['twosided', 'one of the first two child headings is shown, the other asked'],
                                ['multisided', 'any one child heading is shown, the rest asked'],
                                ['hide1cloze, hide2cloze', 'one or two clozes hidden at random, the others shown'],
                                ['show1cloze, show2cloze', 'one or two clozes shown, the others hidden'],
                                ['hidefirst, hidelast', 'only the first, or the last, cloze hidden'],
                                ['hide1_firstmore', 'usually the first cloze hidden, sometimes another'],
                                ['show1_lastmore', 'usually only the last cloze shown'],
                                ['show1_firstless', 'usually one cloze shown, rarely the first'],
                                ['conjugate', 'from VERB_INFINITIVE, VERB_TRANSLATION, VERB_TENSE, VERB_MOOD'],
                                ['decline_noun', 'from NOUN, NOUN_GENDER, NOUN_TRANSLATION, DECLINE_DEFINITE, DECLINE_PLURAL'],
                                ['spanish_verb', 'children called Infinitive and English, asked in a tense'],
                            ].map(([t, d]) => <tr key={t}><td style={{ width: '34%' }}><code>{t}</code></td><td>{d}</td></tr>)}
                        </tbody>
                    </Table>
                    <Typography level="title-md">Drilling</Typography>
                    <Typography level="body-sm">
                        Any key shows the answer; rate it 0-5. 0-2 means forgotten: the card comes back later in the session until
                        you pass it. 3-5 schedules it further away the easier it was - the buttons say how far. <b>e</b> edits the
                        card (the session waits), <b>s</b> skips it, <b>q</b> stops (what you rated is saved; resume from the deck
                        list). Cards come failed first, then overdue, young, then new and old together. Cram reviews everything not
                        seen in the last 12 hours without rescheduling anything.
                    </Typography>
                    <Typography level="title-md" sx={{ mt: 1 }}>More</Typography>
                    <Typography level="body-sm">
                        A child heading with drill data of its own stays folded in the answer. A heading tagged <code>:explain:</code>{' '}
                        over cards adds its text to their answers. <code>:DRILL_CARD_WEIGHT: 2</code> asks a card about twice as
                        often. A card failed too often is tagged <code>leech</code>. The full guide is docs/drill.org.
                    </Typography>
                </Box>
            </ModalDialog>
        </Modal>
    );
}
