import * as React from 'react';
import Box from '@mui/joy/Box';
import Input from '@mui/joy/Input';
import Tooltip from '@mui/joy/Tooltip';
import Typography from '@mui/joy/Typography';
import { useColorScheme } from '@mui/joy/styles';
import SearchIcon from '@mui/icons-material/Search';

import {
    HistoryResult, GraphCommit, layoutGraph, laneColor, relativeTime, initials, authorHue,
    refChips, WORKING, INDEX,
} from '../githistory';

// A file's history as GitKraken draws a repository's: a coloured lane graph
// down the left, a row per commit with its refs, subject, author and when, and
// how much of this file it changed. Uncommitted work sits on top as hollow,
// dashed "work in progress" nodes - the staged copy and the working copy -
// because "what have I changed since my last commit" is the question most
// often asked of a notes file.
//
// A click compares that commit with the one before it; shift or ⌘ clicking a
// second row compares the two, older on the left.

const ROW_H = 46;
const LANE_W = 14;
const PAD = 10;

export type HistoryRow = {
    rev: string;           // a hash, WORKING or INDEX
    pseudo: boolean;
    subject: string;
    author: string;
    when: number;
    short: string;
    refs: string[];
    added: number;
    removed: number;
    parents: string[];
};

// The list's rows: the uncommitted copies on top of the commits.
export function historyRows(h: HistoryResult): HistoryRow[] {
    const rows: HistoryRow[] = [];
    const now = Date.now() / 1000;
    const base = h.Last || '';
    if (h.Staged) {
        rows.push({
            rev: INDEX, pseudo: true, subject: 'Staged changes', author: '', when: now, short: 'index',
            refs: [], added: h.StagedAdd, removed: h.StagedDel, parents: base ? [base] : [],
        });
    }
    if (h.Modified || h.Untracked || !h.InRepo) {
        rows.push({
            rev: WORKING, pseudo: true,
            subject: !h.InRepo ? 'The file on disk' : h.Untracked ? 'Not yet committed' : 'Uncommitted changes',
            author: '', when: now, short: 'working',
            refs: [], added: h.ModifiedAdd, removed: h.ModifiedDel,
            parents: h.Staged ? [INDEX] : base ? [base] : [],
        });
    }
    rows.reverse(); // working copy above the index above the commits
    for (const c of h.Commits || []) {
        rows.push({
            rev: c.Hash, pseudo: false, subject: c.Subject, author: c.Author, when: c.When, short: c.Short,
            refs: c.Refs || [], added: c.Added, removed: c.Removed, parents: c.Parents || [],
        });
    }
    return rows;
}

function Graph({ row, lanes, dark, pseudo, head }: {
    row: ReturnType<typeof layoutGraph>['rows'][number];
    lanes: number;
    dark: boolean;
    pseudo: boolean;
    head: boolean;
}) {
    const w = PAD + lanes * LANE_W;
    const x = (l: number) => PAD / 2 + l * LANE_W + LANE_W / 2;
    const mid = ROW_H / 2;
    const ground = dark ? '#16181d' : '#ffffff';
    const path = (x1: number, y1: number, x2: number, y2: number) =>
        x1 === x2 ? `M${x1},${y1} L${x2},${y2}` : `M${x1},${y1} C${x1},${(y1 + y2) / 2} ${x2},${(y1 + y2) / 2} ${x2},${y2}`;
    const c = laneColor(row.color);
    return (
        <svg width={w} height={ROW_H} style={{ flex: '0 0 auto', display: 'block', overflow: 'visible' }}>
            {row.up.map((s, i) => (
                <path key={'u' + i} d={path(x(s.from), 0, x(s.to), mid)} stroke={laneColor(s.color)} strokeWidth={2}
                    fill="none" strokeDasharray={pseudo && s.to === row.lane ? '3 3' : undefined} />
            ))}
            {row.down.map((s, i) => (
                <path key={'d' + i} d={path(x(s.from), mid, x(s.to), ROW_H)} stroke={laneColor(s.color)} strokeWidth={2}
                    fill="none" strokeDasharray={pseudo && s.from === row.lane ? '3 3' : undefined} />
            ))}
            {pseudo ? (
                <circle cx={x(row.lane)} cy={mid} r={6} fill={ground} stroke={c} strokeWidth={2} strokeDasharray="3 2" />
            ) : (
                <>
                    {head && <circle cx={x(row.lane)} cy={mid} r={9} fill="none" stroke={c} strokeWidth={1.5} opacity={0.5} />}
                    <circle cx={x(row.lane)} cy={mid} r={6} fill={c} stroke={ground} strokeWidth={2} />
                </>
            )}
        </svg>
    );
}

function RefChip({ label, kind, color }: { label: string; kind: string; color: string }) {
    const tag = kind === 'tag';
    return (
        <Box component="span" sx={{
            display: 'inline-flex', alignItems: 'center', gap: 0.4, px: 0.6, borderRadius: tag ? '3px' : '999px',
            fontSize: 10.5, fontWeight: 700, lineHeight: '16px', whiteSpace: 'nowrap',
            color: kind === 'head' ? '#fff' : color,
            bgcolor: kind === 'head' ? color : 'transparent',
            border: `1px ${kind === 'remote' ? 'dashed' : 'solid'} ${color}`,
            maxWidth: 120, overflow: 'hidden', textOverflow: 'ellipsis',
        }}>
            {tag ? '⌂ ' : ''}{label}
        </Box>
    );
}

// How much of the file a commit changed, as a slim two-colour bar scaled to
// the biggest commit in view, so a large rewrite stands out down the list.
function ChurnBar({ added, removed, max }: { added: number; removed: number; max: number }) {
    const total = added + removed;
    if (total === 0) return null;
    const w = Math.max(6, Math.round((Math.log1p(total) / Math.log1p(Math.max(max, 1))) * 44));
    return (
        <Tooltip size="sm" title={`+${added} −${removed} lines`} placement="left">
            <Box sx={{ display: 'flex', width: w, height: 5, borderRadius: 3, overflow: 'hidden', flex: '0 0 auto' }}>
                <Box sx={{ flex: added, bgcolor: 'success.400' }} />
                <Box sx={{ flex: removed, bgcolor: 'danger.400' }} />
            </Box>
        </Tooltip>
    );
}

export default function DiffHistory({ history, base, target, onPick }: {
    history: HistoryResult;
    base: string;
    target: string;
    // A plain click picks a row to see what it changed; with `extend` it
    // becomes the other side of the comparison.
    onPick: (row: HistoryRow, extend: boolean) => void;
}) {
    const { mode, systemMode } = useColorScheme();
    const dark = (mode === 'system' ? systemMode : mode) !== 'light';
    const [filter, setFilter] = React.useState('');

    const rows = React.useMemo(() => historyRows(history), [history]);
    const graph = React.useMemo(
        () => layoutGraph(rows.map(r => ({ Hash: r.rev, Parents: r.parents } as GraphCommit))),
        [rows],
    );
    const maxChurn = React.useMemo(() => rows.reduce((m, r) => Math.max(m, r.added + r.removed), 0), [rows]);
    const q = filter.trim().toLowerCase();
    // Filtering dims rather than hides: the graph is only a graph whole.
    const matches = (r: HistoryRow) => q === '' || r.subject.toLowerCase().includes(q)
        || r.author.toLowerCase().includes(q) || r.short.toLowerCase().startsWith(q);

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', minHeight: 0, flex: 1 }}>
            <Input size="sm" placeholder="Filter by message, author or hash" value={filter}
                onChange={e => setFilter(e.target.value)} startDecorator={<SearchIcon />}
                sx={{ mb: 1, flex: '0 0 auto' }} />
            <Box sx={{ flex: 1, minHeight: 0, overflow: 'auto', borderRadius: 'sm' }}>
                {rows.length === 0 && (
                    <Typography level="body-sm" sx={{ p: 2, color: 'text.tertiary' }}>No history for this file yet.</Typography>
                )}
                {rows.map((r, i) => {
                    const g = graph.rows[i];
                    const isA = r.rev === base;
                    const isB = r.rev === target;
                    const color = laneColor(g.color);
                    const dim = !matches(r);
                    const head = !r.pseudo && r.rev === history.Head;
                    return (
                        <Box key={r.rev} role="button" tabIndex={0}
                            onClick={e => onPick(r, e.shiftKey || e.metaKey || e.ctrlKey)}
                            onKeyDown={e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); onPick(r, e.shiftKey); } }}
                            title={r.pseudo ? undefined : `${r.rev}\n${r.author} · ${new Date(r.when * 1000).toLocaleString()}`}
                            sx={{
                                display: 'flex', alignItems: 'center', height: ROW_H, pr: 1, gap: 0.75,
                                cursor: 'pointer', userSelect: 'none', position: 'relative',
                                opacity: dim ? 0.35 : 1,
                                bgcolor: isB ? 'success.softBg' : isA ? 'danger.softBg' : undefined,
                                '&:hover': { bgcolor: isB ? 'success.softHoverBg' : isA ? 'danger.softHoverBg' : 'background.level1' },
                                outline: 'none',
                                '&:focus-visible': { boxShadow: 'inset 0 0 0 2px var(--joy-palette-focusVisible)' },
                            }}>
                            <Graph row={g} lanes={Math.max(1, graph.lanes)} dark={dark} pseudo={r.pseudo} head={head} />
                            <Box sx={{ minWidth: 0, flex: 1 }}>
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5, minWidth: 0 }}>
                                    {refChips(r.refs).map(c => (
                                        <RefChip key={c.label} label={c.label} kind={c.kind} color={color} />
                                    ))}
                                    <Typography level="body-sm" sx={{
                                        fontWeight: r.pseudo ? 600 : 500, fontStyle: r.pseudo ? 'italic' : undefined,
                                        whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', minWidth: 0,
                                    }}>
                                        {r.subject}
                                    </Typography>
                                </Box>
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.75, mt: '1px', minWidth: 0 }}>
                                    {!r.pseudo && (
                                        <Box sx={{
                                            flex: '0 0 auto', width: 16, height: 16, borderRadius: '50%', fontSize: 8, fontWeight: 800,
                                            display: 'grid', placeItems: 'center', color: '#fff',
                                            bgcolor: `hsl(${authorHue(r.author)} 55% ${dark ? 45 : 48}%)`,
                                        }}>{initials(r.author)}</Box>
                                    )}
                                    <Typography level="body-xs" sx={{ color: 'text.tertiary', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                                        {r.pseudo
                                            ? (r.added + r.removed > 0 ? `+${r.added} −${r.removed} lines` : 'not in git')
                                            : `${r.author} · ${relativeTime(r.when)}`}
                                    </Typography>
                                    {!r.pseudo && (
                                        <Typography level="body-xs" sx={{ fontFamily: 'monospace', color: 'text.tertiary', ml: 'auto', flex: '0 0 auto' }}>
                                            {r.short}
                                        </Typography>
                                    )}
                                    <ChurnBar added={r.added} removed={r.removed} max={maxChurn} />
                                </Box>
                            </Box>
                            {(isA || isB) && (
                                <Box sx={{
                                    position: 'absolute', right: 6, top: 4, width: 16, height: 16, borderRadius: '50%',
                                    display: 'grid', placeItems: 'center', fontSize: 10, fontWeight: 800, color: '#fff',
                                    bgcolor: isB ? 'success.500' : 'danger.500',
                                }}>{isB ? 'B' : 'A'}</Box>
                            )}
                        </Box>
                    );
                })}
                {history.Truncated && (
                    <Typography level="body-xs" sx={{ p: 1.5, color: 'text.tertiary' }}>
                        Older commits are not shown.
                    </Typography>
                )}
            </Box>
        </Box>
    );
}

