// Questions asked of a whole plan, rather than of one bar.
//
// gantt.ts lays the plan out; this reads it back: what has to move when a task
// moves (ripple), how much room each task has before it moves the end date
// (slack), what a lane adds up to (roll-up), how much each person has on each
// day (workload), and what is different from a baseline. Pure, and tested in
// ganttplan.test.ts, because every one of these is arithmetic that still draws
// something plausible when it is wrong.

import {
    GanttModel, GanttTask, GanttServerTask, GanttBaseline, BaselineTask,
    ganttFromTasks, startOfDay, dayKey, nextWorkingDay, healthOf, latestFinish,
} from './gantt';

const DAY_MS = 24 * 60 * 60 * 1000;

// The working day before `d` (or `d` itself when it is one). The other half of
// nextWorkingDay: a task nudged a day earlier from a Monday in a chart that
// skips weekends lands on the Friday, where nextWorkingDay would have bounced
// it straight back to the Monday it started on.
export function prevWorkingDay(d: Date, model: GanttModel): Date {
    let cur = startOfDay(d);
    for (let guard = 0; guard < 400; guard++) {
        if (nextWorkingDay(cur, model).getTime() === cur.getTime()) return cur;
        cur = new Date(cur.getFullYear(), cur.getMonth(), cur.getDate() - 1);
    }
    return startOfDay(d);
}

// The first whole working day at or after a moment. A task that ends half way
// through a day (1.5d of effort) is followed from the next morning.
function dayAtOrAfter(ms: number, model: GanttModel): Date {
    let day = startOfDay(new Date(ms));
    if (day.getTime() < ms) day = new Date(day.getFullYear(), day.getMonth(), day.getDate() + 1);
    return nextWorkingDay(day, model);
}

// --- ripple -----------------------------------------------------------------
//
// Moving or lengthening a task can leave the tasks waiting on it (AFTER)
// starting before it ends. A waiter with no date of its own already follows -
// the scheduler puts it after its predecessor - but one with a SCHEDULED date
// stays put and now overlaps. Rippling pushes those to start the working day
// after, and keeps going down the chain.
//
// It is worked out by scheduling the plan again rather than by restating the
// rules here: the edited rows go back through ganttFromTasks, any dated waiter
// that now starts too early is moved, and that repeats until nothing does. So
// whatever the chart would draw after the write is exactly what this predicts.

export interface RippleChange {
    hash: string;
    // "YYYY-MM-DD", the new start.
    start?: string;
    // The new length, in days of effort.
    effortDays?: number;
}

export interface RippleMove {
    hash: string;
    name: string;
    from: Date;
    to: Date;
    // Calendar days later.
    days: number;
    // True when the move is written (a dated task pushed); false when it
    // follows by itself because it has no date of its own.
    pushed: boolean;
}

export interface RippleOpts {
    excludeWeekends?: boolean;
    laneProp?: string;
    now?: Date;
}

// The rows as they would be after these changes, for scheduling them again:
// a preview of a nudge is the chart drawn from these.
export function withChanges(rows: GanttServerTask[], changes: RippleChange[]): GanttServerTask[] {
    const by = new Map(changes.map(c => [c.hash, c] as [string, RippleChange]));
    return rows.map(r => {
        const c = by.get(r.Hash);
        if (!c) return r;
        return {
            ...r,
            Start: c.start !== undefined ? c.start : r.Start,
            EffortDays: c.effortDays !== undefined ? c.effortDays : r.EffortDays,
        };
    });
}

export function ripple(rows: GanttServerTask[], changes: RippleChange[], opts: RippleOpts = {}): RippleMove[] {
    const sched = { excludeWeekends: opts.excludeWeekends, laneProp: opts.laneProp, now: opts.now };
    const before = ganttFromTasks(rows, sched);
    const was = new Map(before.tasks.filter(t => t.hash).map(t => [t.hash as string, t] as [string, GanttTask]));

    const changed = new Set(changes.map(c => c.hash));
    const work = rows.map(r => ({ ...r }));
    const rowOf = new Map(work.map(r => [r.Hash, r] as [string, GanttServerTask]));
    for (const c of changes) {
        const r = rowOf.get(c.hash);
        if (!r) continue;
        if (c.start !== undefined) r.Start = c.start;
        if (c.effortDays !== undefined) r.EffortDays = c.effortDays;
    }

    const pushed = new Set<string>();
    let after = ganttFromTasks(work, sched);
    for (let pass = 0; pass <= work.length; pass++) {
        const byId = new Map(after.tasks.map(t => [t.id, t] as [string, GanttTask]));
        let moved = false;
        for (const t of after.tasks) {
            if (!t.hash || t.implied || t.mark || t.state === 'done' || !t.dated) continue;
            if (changed.has(t.hash)) continue;
            let latest = 0;
            for (const a of t.after) {
                const dep = byId.get(a);
                if (dep && !dep.mark && dep.end.getTime() > latest) latest = dep.end.getTime();
            }
            if (latest === 0 || t.start.getTime() >= latest) continue;
            const r = rowOf.get(t.hash);
            if (!r) continue;
            r.Start = dayKey(dayAtOrAfter(latest, after));
            pushed.add(t.hash);
            moved = true;
        }
        if (!moved) break;
        after = ganttFromTasks(work, sched);
    }

    const out: RippleMove[] = [];
    for (const t of after.tasks) {
        if (!t.hash || changed.has(t.hash) || t.mark) continue;
        const old = was.get(t.hash);
        if (!old || old.start.getTime() === t.start.getTime()) continue;
        out.push({
            hash: t.hash,
            name: t.name,
            from: old.start,
            to: t.start,
            days: Math.round((startOfDay(t.start).getTime() - startOfDay(old.start).getTime()) / DAY_MS),
            pushed: pushed.has(t.hash),
        });
    }
    return out;
}

// --- slack ------------------------------------------------------------------
//
// criticalPath (gantt.ts) is the tasks with no room at all; slack is how much
// room the rest have. Both read latestFinish.

// How many days each open task could slip before it moved the end of the plan.
// Done and implied tasks have none worth drawing and are left out.
export function slackDays(model: GanttModel): Map<string, number> {
    const lf = latestFinish(model);
    const out = new Map<string, number>();
    for (const t of model.tasks) {
        if (t.mark || t.milestone || t.state === 'done' || t.implied) continue;
        const v = lf.get(t.id);
        if (v === undefined) continue;
        out.set(t.id, Math.max(0, (v - t.end.getTime()) / DAY_MS));
    }
    return out;
}

// --- roll-up ----------------------------------------------------------------
//
// What a lane adds up to, for the bar drawn on its heading: its span, how far
// through it is, how much work is in it, and what in it is late.

export interface Rollup {
    start: Date;
    end: Date;
    count: number;
    done: number;
    overdue: number;
    // Percent done, weighted by each task's planned length: finishing the
    // three-week task matters more than finishing the half day one.
    percent: number;
    // Days of planned work in the lane.
    effort: number;
    // The stretches something in the lane is happening, merged, so a gap in
    // the work shows as a gap in the bar.
    spans: { start: Date; end: Date }[];
    milestones: { date: Date; name: string }[];
}

export function rollup(tasks: GanttTask[], now: Date = new Date()): Rollup | null {
    const drawn = tasks.filter(t => !t.mark);
    if (drawn.length === 0) return null;
    let lo = drawn[0].start;
    let hi = drawn[0].end;
    let done = 0;
    let overdue = 0;
    let weight = 0;
    let doneWeight = 0;
    let effort = 0;
    const ranges: { start: Date; end: Date }[] = [];
    const milestones: { date: Date; name: string }[] = [];
    for (const t of drawn) {
        if (t.start < lo) lo = t.start;
        if (t.end > hi) hi = t.end;
        const finished = t.state === 'done';
        if (finished) done++;
        const h = healthOf(t, now);
        if (h && h.kind === 'overdue') overdue++;
        if (t.milestone) {
            milestones.push({ date: t.start, name: t.name });
            continue;
        }
        const w = t.plannedDays ?? t.days ?? 1;
        effort += t.plannedDays ?? 0;
        weight += w;
        const pct = finished ? 100 : Math.max(0, Math.min(100, t.percent || 0));
        doneWeight += w * pct / 100;
        ranges.push({ start: t.start, end: t.end });
    }
    ranges.sort((a, b) => a.start.getTime() - b.start.getTime());
    const spans: { start: Date; end: Date }[] = [];
    for (const r of ranges) {
        const last = spans[spans.length - 1];
        if (last && r.start.getTime() <= last.end.getTime()) {
            if (r.end > last.end) last.end = r.end;
        } else {
            spans.push({ start: r.start, end: r.end });
        }
    }
    return {
        start: lo, end: hi, count: drawn.length, done, overdue,
        percent: weight > 0 ? Math.round((doneWeight / weight) * 100) : (done === drawn.length ? 100 : 0),
        effort: Math.round(effort * 10) / 10,
        spans, milestones,
    };
}

// --- workload ---------------------------------------------------------------
//
// How much each person has on each day. A task's effort is spread evenly over
// the working days its bar covers: three days of work across a five day bar is
// 0.6 of a day on each, and anything over 1 is a day with more in it than there
// is day. Done, milestone and implied tasks carry none.

// The person a property names. Jira writes ASSIGNED as the display name padded
// out and followed by [email][account id]; the name is the person.
export function personOf(value: string): string {
    return (value || '').replace(/\[[^\]]*\]/g, '').replace(/\s+/g, ' ').trim();
}

// A property read whatever case its name was typed in.
export function propOf(props: Record<string, string> | undefined, name: string): string {
    if (!props || !name) return '';
    if (props[name] !== undefined) return props[name];
    const want = name.toUpperCase();
    for (const k of Object.keys(props)) if (k.toUpperCase() === want) return props[k];
    return '';
}

// The properties that say who a task is for, in the order they are believed.
// ASSIGNED is what the jira plugin writes; ASSIGNEE is what people type.
// Not `resource`, which falls back to the owning project's name - a project
// is not a person, and a face on a task that nobody has is a lie.
export const ASSIGNEE_PROPS = ['ASSIGNEE', 'ASSIGNED', 'RID', 'RESOURCEID'];

export function assigneeOf(t: { props?: Record<string, string> }): string {
    for (const p of ASSIGNEE_PROPS) {
        const who = personOf(propOf(t.props, p));
        if (who) return who;
    }
    return '';
}

// The letters on a person's badge: first and last name's initials, or the
// first two letters of a one-word name or handle.
export function initialsOf(person: string): string {
    const words = personOf(person).replace(/[@.].*$/, '').split(/[\s_-]+/).filter(w => /[\p{L}\p{N}]/u.test(w));
    if (words.length === 0) return '?';
    const first = (w: string) => Array.from(w.replace(/^[^\p{L}\p{N}]+/u, ''))[0] || '';
    if (words.length === 1) return Array.from(words[0]).slice(0, 2).join('').toUpperCase();
    return (first(words[0]) + first(words[words.length - 1])).toUpperCase();
}

export const NOBODY = '(nobody)';

export interface WorkloadRow {
    person: string;
    // Days of work on each day, by dayKey.
    load: Map<string, number>;
    peak: number;
    tasks: number;
}

export function workload(model: GanttModel, prop: string): WorkloadRow[] {
    const rows = new Map<string, WorkloadRow>();
    for (const t of model.tasks) {
        if (t.mark || t.milestone || t.implied || t.state === 'done') continue;
        const person = personOf(propOf(t.props, prop)) || NOBODY;
        const days: string[] = [];
        const first = startOfDay(t.start);
        for (let d = first; d < t.end; d = new Date(d.getFullYear(), d.getMonth(), d.getDate() + 1)) {
            if (nextWorkingDay(d, model).getTime() === d.getTime()) days.push(dayKey(d));
            if (days.length > 2000) break;
        }
        if (days.length === 0) continue;
        const planned = t.plannedDays ?? days.length;
        const each = planned / days.length;
        let row = rows.get(person);
        if (!row) {
            row = { person, load: new Map(), peak: 0, tasks: 0 };
            rows.set(person, row);
        }
        row.tasks++;
        for (const k of days) {
            const v = (row.load.get(k) || 0) + each;
            row.load.set(k, v);
            if (v > row.peak) row.peak = v;
        }
    }
    return Array.from(rows.values()).sort((a, b) => {
        if (a.person === NOBODY) return 1;
        if (b.person === NOBODY) return -1;
        return a.person.localeCompare(b.person, undefined, { sensitivity: 'base' });
    });
}

// The people the chart could be split by: every distinct value of the
// property, for the picker to show before anything is chosen.
export function workloadProps(tasks: GanttTask[]): string[] {
    const seen = new Set<string>();
    for (const t of tasks) Object.keys(t.props || {}).forEach(k => seen.add(k.toUpperCase()));
    return Array.from(seen).sort();
}

// --- what changed since a baseline ------------------------------------------

export type PlanChangeKind = 'moved' | 'longer' | 'shorter' | 'added' | 'removed';

export interface PlanChange {
    kind: PlanChangeKind;
    name: string;
    // The task as it is now; none for a task that has gone.
    hash?: string;
    // Days the start moved (later is positive), and days the length changed.
    startDelta: number;
    lengthDelta: number;
    // How far the end moved, which is what anybody waiting on it cares about.
    endDelta: number;
}

const KIND_ORDER: PlanChangeKind[] = ['moved', 'longer', 'shorter', 'added', 'removed'];

export function baselineChanges(model: GanttModel, base: GanttBaseline | null | undefined): PlanChange[] {
    if (!base) return [];
    const byHash = new Map<string, BaselineTask>();
    const byName = new Map<string, BaselineTask>();
    for (const x of base.tasks || []) {
        byHash.set(x.hash, x);
        byName.set(`${x.filename}\u0000${x.headline}`, x);
    }
    const matched = new Set<BaselineTask>();
    const out: PlanChange[] = [];
    const days = (ms: number) => Math.round(ms / DAY_MS);
    for (const t of model.tasks) {
        if (t.mark || t.implied || !t.hash) continue;
        const x = byHash.get(t.hash) || byName.get(`${t.filename || ''}\u0000${t.name}`);
        if (!x) {
            out.push({ kind: 'added', name: t.name, hash: t.hash, startDelta: 0, lengthDelta: 0, endDelta: 0 });
            continue;
        }
        matched.add(x);
        const bs = new Date(x.start).getTime();
        const be = new Date(x.end).getTime();
        const startDelta = days(startOfDay(t.start).getTime() - startOfDay(new Date(bs)).getTime());
        const lengthDelta = days((t.end.getTime() - t.start.getTime()) - (be - bs));
        const endDelta = days(t.end.getTime() - be);
        if (startDelta !== 0) out.push({ kind: 'moved', name: t.name, hash: t.hash, startDelta, lengthDelta, endDelta });
        else if (lengthDelta > 0) out.push({ kind: 'longer', name: t.name, hash: t.hash, startDelta, lengthDelta, endDelta });
        else if (lengthDelta < 0) out.push({ kind: 'shorter', name: t.name, hash: t.hash, startDelta, lengthDelta, endDelta });
    }
    for (const x of base.tasks || []) {
        if (!matched.has(x)) out.push({ kind: 'removed', name: x.headline, startDelta: 0, lengthDelta: 0, endDelta: 0 });
    }
    return out.sort((a, b) => {
        const k = KIND_ORDER.indexOf(a.kind) - KIND_ORDER.indexOf(b.kind);
        if (k !== 0) return k;
        return Math.abs(b.endDelta) - Math.abs(a.endDelta) || a.name.localeCompare(b.name);
    });
}
