// React's view of the browser stored settings in settings.ts.

import * as React from 'react';
import {
    UserSettings,
    getSettings,
    setSetting,
    subscribeSettings,
    resolveHtmlTheme,
} from './settings';
import { useColorScheme } from '@mui/joy/styles';

// Every setting, re-rendering whenever any of them changes.
export function useSettings(): UserSettings {
    return React.useSyncExternalStore(subscribeSettings, getSettings, getSettings);
}

// One setting and a setter for it, in the shape of useState.
export function useSetting<K extends keyof UserSettings>(
    key: K,
): [UserSettings[K], (v: UserSettings[K]) => void] {
    const all = useSettings();
    const set = React.useCallback((v: UserSettings[K]) => setSetting(key, v), [key]);
    return [all[key], set];
}

// The theme name to ask the exporter for, with "auto" already turned into the
// one that matches the app's light or dark mode. Empty means: leave the file's
// own #+HTML_THEME alone.
export function useHtmlTheme(): string {
    const { mode, systemMode } = useColorScheme();
    const [setting] = useSetting('htmlTheme');
    return resolveHtmlTheme(setting, mode === 'system' ? systemMode : mode);
}
