// A new org file: a template, a folder picked fzf-style from every folder under
// the org directories (or a new folder made inside one), a name, and a title.
// Opened from the rail's "new file" button and the command palette; the file
// it makes opens in the Files tab.
//
// The picker is the whole point of the dialog, so it is keyboard first: the
// search has focus when the dialog opens, ↑/↓ move through the folders, Enter
// takes the highlighted one and moves on to the name, and Enter in the name
// makes the file. The folder last used is where the next one starts.

import * as React from 'react';
import Modal from '@mui/joy/Modal';
import ModalDialog from '@mui/joy/ModalDialog';
import ModalClose from '@mui/joy/ModalClose';
import Typography from '@mui/joy/Typography';
import Box from '@mui/joy/Box';
import Input from '@mui/joy/Input';
import Button from '@mui/joy/Button';
import Chip from '@mui/joy/Chip';
import Switch from '@mui/joy/Switch';
import FormControl from '@mui/joy/FormControl';
import FormLabel from '@mui/joy/FormLabel';
import CircularProgress from '@mui/joy/CircularProgress';
import SearchIcon from '@mui/icons-material/Search';
import FolderIcon from '@mui/icons-material/FolderOutlined';
import CreateNewFolderIcon from '@mui/icons-material/CreateNewFolderOutlined';
import NoteAddIcon from '@mui/icons-material/NoteAddOutlined';
import { ODb } from '../db';
import {
    rootsOf, rankDirs, dirLabel, nameError, newFilePath, titleFromName, templateLabel,
} from '../newfile';

const LAST_DIR = 'worg.newFile.dir';
const LAST_TEMPLATE = 'worg.newFile.template';

function remembered(key: string): string {
    try { return localStorage.getItem(key) || ''; } catch { return ''; }
}
function remember(key: string, v: string) {
    try { localStorage.setItem(key, v); } catch { /* private window: forget it */ }
}

// A label with the letters the search matched drawn bold and in colour.
function Highlit({ text, hits }: { text: string; hits: number[] }) {
    if (hits.length === 0) return <>{text}</>;
    const on = new Set(hits);
    const out: React.ReactNode[] = [];
    let run = '';
    let runOn = false;
    const flush = (k: number) => {
        if (!run) return;
        out.push(runOn
            ? <Box key={k} component="span" sx={{ color: 'primary.plainColor', fontWeight: 700 }}>{run}</Box>
            : <React.Fragment key={k}>{run}</React.Fragment>);
        run = '';
    };
    Array.from(text).forEach((ch, i) => {
        const h = on.has(i);
        if (h !== runOn) { flush(i); runOn = h; }
        run += ch;
    });
    flush(text.length);
    return <>{out}</>;
}

export default function NewFileDialog({ open, onClose, onCreated }: {
    open: boolean;
    onClose: () => void;
    // The path of the file just made.
    onCreated: (filename: string) => void;
}) {
    const [templates, setTemplates] = React.useState<string[]>([]);
    const [dirs, setDirs] = React.useState<string[]>([]);
    const [loading, setLoading] = React.useState(false);
    const [template, setTemplate] = React.useState('');
    const [filter, setFilter] = React.useState('');
    const [cursor, setCursor] = React.useState(0);
    const [parent, setParent] = React.useState('');
    const [makeFolder, setMakeFolder] = React.useState(false);
    const [folder, setFolder] = React.useState('');
    const [name, setName] = React.useState('');
    const [title, setTitle] = React.useState('');
    const [busy, setBusy] = React.useState(false);
    const [error, setError] = React.useState('');
    const listRef = React.useRef<HTMLDivElement>(null);
    const nameRef = React.useRef<HTMLInputElement>(null);
    const folderRef = React.useRef<HTMLInputElement>(null);

    // Asked afresh each time it opens: folders come and go.
    React.useEffect(() => {
        if (!open) return;
        let alive = true;
        setLoading(true);
        setError('');
        setFilter('');
        setCursor(0);
        setName('');
        setTitle('');
        setFolder('');
        setMakeFolder(false);
        Promise.all([ODb.getNewFileTemplates(), ODb.getAllDirs()]).then(([ts, ds]) => {
            if (!alive) return;
            const tlist = (ts || []).slice().sort();
            setTemplates(tlist);
            const lastT = remembered(LAST_TEMPLATE);
            setTemplate(tlist.indexOf(lastT) >= 0 ? lastT : '');
            const dlist = Array.isArray(ds) ? ds : [];
            setDirs(dlist);
            const lastD = remembered(LAST_DIR);
            setParent(dlist.indexOf(lastD) >= 0 ? lastD : (rootsOf(dlist)[0] || ''));
            setLoading(false);
        }).catch(e => {
            if (!alive) return;
            setLoading(false);
            setError(e?.message || 'Could not ask the server for its folders');
        });
        return () => { alive = false; };
    }, [open]);

    const roots = React.useMemo(() => rootsOf(dirs), [dirs]);
    const ranked = React.useMemo(() => rankDirs(dirs, filter, roots), [dirs, filter, roots]);
    // The list shows a screenful; the search narrows it.
    const shown = ranked.slice(0, 200);
    React.useEffect(() => { setCursor(0); }, [filter]);
    React.useEffect(() => {
        const el = listRef.current?.querySelector(`[data-row="${cursor}"]`) as HTMLElement | null;
        el?.scrollIntoView({ block: 'nearest' });
    }, [cursor]);

    const pick = (dir: string) => {
        setParent(dir);
        // On to the next thing to type.
        window.setTimeout(() => (makeFolder ? folderRef.current : nameRef.current)?.focus(), 0);
    };

    const onSearchKey = (e: React.KeyboardEvent) => {
        if (e.key === 'ArrowDown') { setCursor(c => Math.min(c + 1, shown.length - 1)); e.preventDefault(); }
        else if (e.key === 'ArrowUp') { setCursor(c => Math.max(c - 1, 0)); e.preventDefault(); }
        else if (e.key === 'Enter' && shown[cursor]) { pick(shown[cursor].dir); e.preventDefault(); }
    };

    const nameErr = name ? nameError(name, 'file') : '';
    const folderErr = makeFolder && folder ? nameError(folder, 'folder') : '';
    const path = parent && name.trim() ? newFilePath(parent, makeFolder ? folder : '', name) : '';
    const ready = !!path && !nameErr && !folderErr && (!makeFolder || folder.trim() !== '') && !busy;

    const create = async () => {
        if (!ready) return;
        setBusy(true);
        setError('');
        try {
            const res = await ODb.createOrgFile({
                filename: path,
                title: title.trim() || titleFromName(name),
                template,
            });
            if (Array.isArray(res) && res.length > 0) {
                remember(LAST_DIR, parent);
                remember(LAST_TEMPLATE, template);
                onClose();
                onCreated(res[0]);
            } else {
                setError((res as any)?.Msg || 'The server did not make the file');
            }
        } catch (e: any) {
            setError(e?.message || 'The file could not be made');
        } finally {
            setBusy(false);
        }
    };

    return (
        <Modal open={open} onClose={onClose}>
            <ModalDialog sx={{ width: 'min(620px, 96vw)', maxHeight: '92dvh', overflowY: 'auto', gap: 1.5 }}>
                <ModalClose />
                <Typography level="title-lg" startDecorator={<NoteAddIcon />}>New org file</Typography>

                {loading ? (
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, py: 3 }}>
                        <CircularProgress size="sm" />
                        <Typography level="body-sm">Reading the folders…</Typography>
                    </Box>
                ) : (
                    <>
                        <FormControl size="sm">
                            <FormLabel>Template</FormLabel>
                            <Box sx={{ display: 'flex', gap: 0.75, flexWrap: 'wrap' }}>
                                {['', ...templates].map(t => (
                                    <Chip
                                        key={t || 'default'}
                                        variant={template === t ? 'solid' : 'outlined'}
                                        color={template === t ? 'primary' : 'neutral'}
                                        onClick={() => setTemplate(t)}
                                        title={t || 'The server\'s own newFileTemplate'}
                                    >
                                        {t ? templateLabel(t) : 'Plain'}
                                    </Chip>
                                ))}
                            </Box>
                        </FormControl>

                        <FormControl size="sm">
                            <FormLabel>Where</FormLabel>
                            <Input
                                size="sm" autoFocus
                                value={filter}
                                onChange={e => setFilter(e.target.value)}
                                onKeyDown={onSearchKey}
                                placeholder="Type to find a folder - ↑↓ to move, Enter to choose"
                                startDecorator={<SearchIcon />}
                                endDecorator={<Typography level="body-xs" sx={{ color: 'text.tertiary' }}>{`${ranked.length}/${dirs.length}`}</Typography>}
                                slotProps={{ input: { spellCheck: false, 'aria-label': 'Find a folder' } }}
                                sx={{ fontFamily: 'monospace' }}
                            />
                            <Box
                                ref={listRef}
                                role="listbox"
                                sx={{
                                    mt: 0.75, maxHeight: 220, overflowY: 'auto', borderRadius: 'sm',
                                    border: '1px solid', borderColor: 'neutral.outlinedBorder', bgcolor: 'background.level1',
                                    fontFamily: 'monospace', fontSize: 12.5,
                                }}
                            >
                                {shown.length === 0 && (
                                    <Typography level="body-xs" sx={{ p: 1, color: 'text.tertiary' }}>No folder matches</Typography>
                                )}
                                {shown.map((r, i) => {
                                    const isCur = i === cursor;
                                    const isPicked = r.dir === parent;
                                    return (
                                        <Box
                                            key={r.dir}
                                            data-row={i}
                                            role="option"
                                            aria-selected={isPicked}
                                            onMouseEnter={() => setCursor(i)}
                                            onMouseDown={e => { e.preventDefault(); pick(r.dir); }}
                                            sx={{
                                                display: 'flex', alignItems: 'center', gap: 0.75, px: 1, py: 0.4, cursor: 'pointer',
                                                bgcolor: isCur ? 'primary.softBg' : 'transparent',
                                                borderLeft: '3px solid', borderLeftColor: isPicked ? 'primary.500' : 'transparent',
                                                whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis',
                                            }}
                                        >
                                            <Box component="span" sx={{ color: isCur ? 'primary.500' : 'text.tertiary', width: 10, flex: 'none' }}>
                                                {isCur ? '›' : ''}
                                            </Box>
                                            <FolderIcon sx={{ fontSize: 15, color: isPicked ? 'primary.500' : 'text.tertiary', flex: 'none' }} />
                                            <Box component="span" sx={{ overflow: 'hidden', textOverflow: 'ellipsis' }}>
                                                <Highlit text={r.label} hits={r.hits} />
                                            </Box>
                                        </Box>
                                    );
                                })}
                            </Box>
                            <Typography level="body-xs" sx={{ mt: 0.5, color: 'text.secondary' }}>
                                {parent ? <>In <b>{dirLabel(parent, roots)}</b></> : 'Pick a folder'}
                            </Typography>
                        </FormControl>

                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                            <Switch
                                size="sm" checked={makeFolder}
                                onChange={e => {
                                    setMakeFolder(e.target.checked);
                                    if (e.target.checked) window.setTimeout(() => folderRef.current?.focus(), 0);
                                }}
                                startDecorator={<CreateNewFolderIcon sx={{ fontSize: 18 }} />}
                            />
                            <Typography level="body-sm">In a new folder</Typography>
                            {makeFolder && (
                                <Input
                                    size="sm" value={folder}
                                    onChange={e => setFolder(e.target.value)}
                                    onKeyDown={e => { if (e.key === 'Enter') nameRef.current?.focus(); }}
                                    placeholder="folder name (a/b makes both)"
                                    error={!!folderErr}
                                    slotProps={{ input: { ref: folderRef, spellCheck: false, 'aria-label': 'New folder name' } }}
                                    sx={{ flex: 1, fontFamily: 'monospace' }}
                                />
                            )}
                        </Box>
                        {makeFolder && (
                            <Typography level="body-xs" sx={{ mt: -1, color: folderErr ? 'danger.500' : 'text.tertiary' }}>
                                {folderErr || `Made inside ${parent ? dirLabel(parent, roots) : 'the folder you pick above'}`}
                            </Typography>
                        )}

                        <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
                            <FormControl size="sm" sx={{ flex: 1, minWidth: 200 }} error={!!nameErr}>
                                <FormLabel>File name</FormLabel>
                                <Input
                                    size="sm" value={name}
                                    onChange={e => setName(e.target.value)}
                                    onKeyDown={e => { if (e.key === 'Enter') create(); }}
                                    placeholder="planning"
                                    endDecorator={<Typography level="body-xs" sx={{ color: 'text.tertiary' }}>.org</Typography>}
                                    slotProps={{ input: { ref: nameRef, spellCheck: false, 'aria-label': 'File name' } }}
                                    sx={{ fontFamily: 'monospace' }}
                                />
                            </FormControl>
                            <FormControl size="sm" sx={{ flex: 1, minWidth: 200 }}>
                                <FormLabel>Title</FormLabel>
                                <Input
                                    size="sm" value={title}
                                    onChange={e => setTitle(e.target.value)}
                                    onKeyDown={e => { if (e.key === 'Enter') create(); }}
                                    placeholder={name ? titleFromName(name) : 'From the file name'}
                                />
                            </FormControl>
                        </Box>
                        {nameErr && <Typography level="body-xs" sx={{ mt: -1, color: 'danger.500' }}>{nameErr}</Typography>}

                        <Box sx={{
                            px: 1, py: 0.75, borderRadius: 'sm', bgcolor: 'background.level1',
                            fontFamily: 'monospace', fontSize: 12, color: path ? 'text.primary' : 'text.tertiary',
                            wordBreak: 'break-all',
                        }}>
                            {path ? dirLabel(path, roots) : 'The new file’s path shows here'}
                        </Box>

                        {error && <Typography level="body-sm" color="danger">{error}</Typography>}

                        <Box sx={{ display: 'flex', justifyContent: 'flex-end', gap: 1 }}>
                            <Button variant="plain" color="neutral" onClick={onClose}>Cancel</Button>
                            <Button startDecorator={<NoteAddIcon />} disabled={!ready} loading={busy} onClick={create}>
                                Create and open
                            </Button>
                        </Box>
                    </>
                )}
            </ModalDialog>
        </Modal>
    );
}
