// The clock that is running right now.
//
// Org's clock is a single thing: one heading at a time is being timed, and the
// server knows which. Two tabs care - the search table, which is where you
// start and stop it, and the clock report, which is otherwise a picture of
// time that has already been written down and would quietly leave out the
// hour you are in the middle of.
//
// So the elapsed-time counter and the poll live here rather than in either of
// them. Two copies of "how long has this been running" is two clocks that
// disagree by a second, which is the kind of thing that makes a page look
// broken for no useful reason.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Chip from '@mui/joy/Chip';
import Sheet from '@mui/joy/Sheet';
import Typography from '@mui/joy/Typography';
import Tooltip from '@mui/joy/Tooltip';
import Button from '@mui/joy/Button';

import TimerRoundedIcon from '@mui/icons-material/TimerRounded';
import StopRoundedIcon from '@mui/icons-material/StopRounded';

import * as Db from '../db';

// How long a clock has been running, counting up. Seconds are shown because a
// clock that only moves once a minute looks stopped.
export function elapsedSince(startMs: number, nowMs: number): string {
    const diff = Math.max(0, nowMs - startMs);
    const hrs = Math.floor(diff / 3600000);
    const mins = Math.floor((diff % 3600000) / 60000);
    const secs = Math.floor((diff % 60000) / 1000);
    return hrs > 0
        ? `${hrs}:${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`
        : `${mins}:${String(secs).padStart(2, '0')}`;
}

export function ClockTimer({ startTime }: { startTime: string }) {
    const [elapsed, setElapsed] = React.useState('');
    React.useEffect(() => {
        const start = new Date(startTime).getTime();
        const update = () => setElapsed(elapsedSince(start, Date.now()));
        update();
        const interval = setInterval(update, 1000);
        return () => clearInterval(interval);
    }, [startTime]);
    return (
        <Chip
            size="sm"
            variant="soft"
            color="success"
            startDecorator={<TimerRoundedIcon sx={{ fontSize: 14 }} />}
            sx={{ fontFamily: 'monospace', fontSize: '11px' }}
        >
            {elapsed}
        </Chip>
    );
}

export interface RunningClock {
    // The heading being timed, and the file it is in.
    headline: string;
    filename: string;
    // The whole outline path, which is what the server actually answers with.
    olp: string;
    // When it started, as the server said it.
    start: string;
}

// What the server says is running, or null. The shape is the clock endpoint's:
// a target given as a file and an outline path rather than a hash, because a
// hash changes when the heading does and a clock outlives an edit.
export function clockFrom(state: any): RunningClock | null {
    if (!state || Array.isArray(state) || typeof state !== 'object') return null;
    if (!state.Active || !state.Target) return null;
    const olp = state.Target.Id || '';
    const start = (state.Time && state.Time.Start) || '';
    if (start === '') return null;
    return {
        headline: olp.split('::').pop() || '',
        filename: state.Target.Filename || '',
        olp,
        start,
    };
}

// Ask the server what is running, and keep asking. `everyMs` is deliberately
// unhurried: the counter runs off the start time locally, so the poll is only
// there to notice a clock started or stopped somewhere else.
export function useRunningClock(everyMs: number = 30000): {
    clock: RunningClock | null;
    refresh: () => void;
} {
    const [clock, setClock] = React.useState<RunningClock | null>(null);
    const alive = React.useRef(true);

    const refresh = React.useCallback(async () => {
        try {
            const state = await Db.ODb.getClockState();
            if (alive.current) setClock(clockFrom(state));
        } catch {
            // A clock nobody can reach is not a clock that stopped, so the
            // last reading stands rather than the banner blinking out.
        }
    }, []);

    React.useEffect(() => {
        alive.current = true;
        refresh();
        const t = setInterval(refresh, everyMs);
        return () => { alive.current = false; clearInterval(t); };
    }, [everyMs, refresh]);

    return { clock, refresh };
}

// The banner over the clock report. It is the one row of the report that is
// still being written, so it sits above the table rather than in it - a row
// whose number changes while you read it does not belong in a total.
export function ActiveClockBanner({ clock, onStopped }: {
    clock: RunningClock | null;
    onStopped?: () => void;
}) {
    const [stopping, setStopping] = React.useState(false);

    if (!clock) {
        return (
            <Sheet
                variant="soft"
                sx={{
                    borderRadius: 'sm', px: 2, py: 1.25,
                    display: 'flex', alignItems: 'center', gap: 1,
                }}
            >
                <TimerRoundedIcon sx={{ fontSize: 16, color: 'text.tertiary' }} />
                <Typography level="body-sm" sx={{ color: 'text.tertiary' }}>
                    No clock is running. Start one from the Search tab.
                </Typography>
            </Sheet>
        );
    }

    const stop = async () => {
        setStopping(true);
        try {
            await Db.ODb.clockOut();
        } catch {
            // The next poll says what really happened.
        }
        setStopping(false);
        if (onStopped) onStopped();
    };

    const started = new Date(clock.start);
    const startedLabel = isNaN(started.getTime())
        ? clock.start
        : started.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

    return (
        <Sheet
            variant="soft"
            color="success"
            sx={{
                borderRadius: 'sm', px: 2, py: 1.25,
                display: 'flex', alignItems: 'center', gap: 1.5, flexWrap: 'wrap',
                // A pulse on the dot rather than on the whole banner: it says
                // "still going" from the corner of the eye without the page
                // moving while somebody is reading a table.
                '& .ac-dot': { animation: 'ac-pulse 2s ease-in-out infinite' },
                '@keyframes ac-pulse': {
                    '0%, 100%': { opacity: 1 },
                    '50%': { opacity: 0.35 },
                },
            }}
        >
            <Box className="ac-dot" sx={{
                width: 8, height: 8, borderRadius: '50%', flexShrink: 0,
                background: 'var(--joy-palette-success-solidBg)',
            }} />
            <Typography level="body-xs" sx={{
                fontWeight: 'lg', letterSpacing: '0.07em', textTransform: 'uppercase',
                color: 'text.tertiary',
            }}>
                Clocked in
            </Typography>

            <Tooltip size="sm" title={clock.olp || clock.headline}>
                <Typography level="title-sm" noWrap sx={{ minWidth: 0, maxWidth: 420 }}>
                    {clock.headline || '(a heading)'}
                </Typography>
            </Tooltip>

            <ClockTimer startTime={clock.start} />

            <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                since {startedLabel}
                {clock.filename ? ` · ${clock.filename.split('/').pop()}` : ''}
            </Typography>

            <Button
                size="sm"
                variant="soft"
                color="danger"
                loading={stopping}
                startDecorator={<StopRoundedIcon />}
                onClick={stop}
                sx={{ ml: 'auto' }}
            >
                Clock out
            </Button>
        </Sheet>
    );
}
